// 病句 코스 8 — tools/make_bingju.py 가 tools/bingju/c08.json 에서 만든다. 직접 고치지 않는다.
(window.BJ=window.BJ||{})[8]=[[{"o":["通过对塔克拉玛干沙漠边缘数十年的植被监测，使科研人员发现梭梭林能有效遏制流沙南移。","盾构机能在地下一边掘进一边拼装管片，被形象地称为隧道施工中的“钢铁穿山甲”。","宋代饮茶之风盛行于朝野，点茶、斗茶等技艺在文人雅士之间广为流传。","臭氧层能够吸收太阳光中绝大部分的紫外线，从而为地球上的生物提供了一道天然屏障。"],"a":0,"type":"주어 결여","why":"“通过……，使……” 때문에 문장에 주어가 없다. 발견한 사람인 “科研人员”이 “使”의 목적어가 되어 버렸다.","fix":"通过对塔克拉玛干沙漠边缘数十年的植被监测，科研人员发现梭梭林能有效遏制流沙南移。","words":[["塔克拉玛干","Tǎkèlāmǎgān","타클라마칸(사막)"],["梭梭","suōsuō","사막 관목의 하나(삭사울)"],["遏制","èzhì","억제하다, 막다"],["盛行","shèngxíng","성행하다"],["臭氧层","chòuyǎngcéng","오존층"],["屏障","píngzhàng","방벽, 보호막"],["盾构机","dùngòujī","실드 굴진기(터널 굴착기)"],["掘进","juéjìn","굴진하다"]],"tr":["타클라마칸 사막 가장자리의 식생을 수십 년간 관찰한 결과, 연구진은 사삭나무 숲이 모래가 남쪽으로 밀려오는 것을 효과적으로 막아 준다는 사실을 알아냈다.","실드 굴진기는 땅속을 파 나가면서 동시에 세그먼트를 조립할 수 있어 터널 공사의 '강철 천산갑'이라 불린다.","송나라 때는 차 마시는 풍습이 조정과 민간에 두루 퍼졌고, 점다·투다 같은 기예가 문인들 사이에서 널리 전해졌다.","오존층은 햇빛 속 자외선을 대부분 흡수해 지구 생물에게 천연 보호막이 되어 준다."],"ow":[[["塔克拉玛干","Tǎkèlāmǎgān","타클라마칸(사막)"],["植被","zhíbèi","식생"],["监测","jiāncè","관측하다"],["梭梭","suōsuō","사삭나무(사막 관목)"],["遏制","èzhì","억제하다, 막다"]],[["盾构机","dùngòujī","실드 굴진기"],["掘进","juéjìn","굴진하다"],["拼装","pīnzhuāng","조립하다"],["管片","guǎnpiàn","세그먼트(터널 벽 조각)"],["穿山甲","chuānshānjiǎ","천산갑"]],[["盛行","shèngxíng","성행하다"],["朝野","cháoyě","조정과 민간"],["文人雅士","wénrén yǎshì","문인과 선비"],["广为流传","guǎng wéi liúchuán","널리 전해지다"]],[["臭氧层","chòuyǎngcéng","오존층"],["紫外线","zǐwàixiàn","자외선"],["屏障","píngzhàng","방벽, 보호막"]]]},{"o":["秦岭是我国南北方重要的地理分界线，其南北两侧的气候、植被与农业形态差异显著。","随着全球气温持续升高，使北极海冰的覆盖面积在夏季屡创历史新低。","明代医药学家李时珍历时二十七年，编成了被誉为“东方医药巨典”的《本草纲目》。","人在长期焦虑的状态下，体内皮质醇水平往往居高不下，免疫力也会随之减弱。"],"a":1,"type":"주어 결여","why":"“随着……，使……” 때문에 주어가 사라졌다. “使”를 빼야 “北极海冰的覆盖面积”가 주어가 된다.","fix":"随着全球气温持续升高，北极海冰的覆盖面积在夏季屡创历史新低。","words":[["秦岭","Qín Lǐng","친링산맥"],["分界线","fēnjièxiàn","경계선"],["屡创","lǚchuàng","거듭 세우다"],["李时珍","Lǐ Shízhēn","리스전(명대 의학자)"],["本草纲目","Běncǎo Gāngmù","본초강목"],["皮质醇","pízhìchún","코르티솔"],["居高不下","jū gāo bú xià","높은 수준에서 내려오지 않다"]],"tr":["친링산맥은 중국 남북을 가르는 중요한 지리적 경계선으로, 남쪽과 북쪽의 기후·식생·농업 형태가 뚜렷이 다르다.","지구 기온이 계속 오르면서 북극 해빙의 면적은 여름마다 거듭 역대 최저치를 기록하고 있다.","명나라 의학자 리스전은 27년에 걸쳐 '동양 의학의 거대한 경전'으로 불리는 『본초강목』을 완성했다.","오랫동안 불안한 상태에 있으면 몸속 코르티솔 수치가 높게 유지되고 면역력도 따라서 약해진다."],"ow":[[["秦岭","Qín Lǐng","친링산맥"],["分界线","fēnjièxiàn","경계선"],["植被","zhíbèi","식생"],["差异显著","chāyì xiǎnzhù","차이가 뚜렷하다"]],[["海冰","hǎibīng","해빙(바다 얼음)"],["覆盖","fùgài","덮다"],["屡创","lǚ chuàng","거듭 세우다"]],[["李时珍","Lǐ Shízhēn","리스전"],["历时","lìshí","시간이 걸리다"],["誉为","yùwéi","~로 칭송되다"],["本草纲目","Běncǎo Gāngmù","본초강목"]],[["焦虑","jiāolǜ","불안하다"],["皮质醇","pízhìchún","코르티솔"],["居高不下","jū gāo bú xià","높은 수준에서 내려오지 않다"],["免疫力","miǎnyìlì","면역력"]]]},{"o":["沉管隧道的管节先在干坞中预制完成，再被浮运到指定海域，沉放到海底后逐节对接。","京剧融唱、念、做、打于一体，以程式化的表演手法塑造了众多鲜明的人物形象。","在当地政府与牧民的共同努力下，让曾经濒临干涸的居延海重新碧波荡漾。","斜拉桥依靠从桥塔上斜向引出的众多拉索承受桥面荷载，外形宛如一把展开的竖琴。"],"a":2,"type":"주어 결여","why":"“在……下，让……” 때문에 주어가 없다. “让”을 빼야 “居延海”가 주어가 된다.","fix":"在当地政府与牧民的共同努力下，曾经濒临干涸的居延海重新碧波荡漾。","words":[["程式化","chéngshìhuà","정형화된"],["濒临","bīnlín","(위기에) 처하다, 임박하다"],["干涸","gānhé","말라붙다"],["居延海","Jūyán Hǎi","쥐옌하이(내몽골의 호수)"],["沉管","chénguǎn","침매(가라앉혀 잇는) 관"],["干坞","gānwù","드라이 독"],["斜拉桥","xiélāqiáo","사장교"],["荷载","hèzài","하중"]],"tr":["침매 터널은 관 조각을 먼저 드라이 독에서 만들어 지정 해역으로 띄워 옮긴 뒤 바닷속에 가라앉혀 하나씩 잇는다.","경극은 노래·대사·연기·무술을 하나로 아우르며, 정형화된 연기 방식으로 개성 뚜렷한 인물을 많이 만들어 냈다.","지방 정부와 목축민이 함께 애쓴 덕분에, 한때 말라붙을 뻔했던 쥐옌하이 호수에 다시 푸른 물결이 일렁이게 되었다.","사장교는 주탑에서 비스듬히 뻗어 나온 수많은 케이블로 다리 상판의 하중을 견디며, 모양이 펼쳐 놓은 하프 같다."],"ow":[[["沉管隧道","chénguǎn suìdào","침매 터널"],["干坞","gānwù","드라이 독"],["预制","yùzhì","미리 제작하다"],["浮运","fúyùn","띄워 운반하다"],["对接","duìjiē","맞붙여 잇다"]],[["京剧","jīngjù","경극"],["程式化","chéngshìhuà","정형화된"],["塑造","sùzào","(인물을) 형상화하다"],["鲜明","xiānmíng","뚜렷하다"]],[["牧民","mùmín","목축민"],["濒临","bīnlín","직면하다, 임박하다"],["干涸","gānhé","말라붙다"],["居延海","Jūyán Hǎi","쥐옌하이(호수)"],["碧波荡漾","bìbō dàngyàng","푸른 물결이 일렁이다"]],[["斜拉桥","xiélāqiáo","사장교"],["桥塔","qiáotǎ","주탑"],["拉索","lāsuǒ","케이블"],["荷载","hèzài","하중"],["宛如","wǎnrú","마치 ~같다"],["竖琴","shùqín","하프"]]]},{"o":["悬索桥的主缆由数万根高强度钢丝组成，两端通过巨大的锚碇牢牢固定在岩体中。","北宋时期，毕昇发明了活字印刷术，这比欧洲同类技术的出现早了约四百年。","大熊猫的祖先曾是食肉动物，后来才逐渐演化为以竹子为主要食物的物种。","由于长期过度捕捞和近海污染，令渤海的许多传统经济鱼类几乎绝迹。"],"a":3,"type":"주어 결여","why":"“由于……，令……” 때문에 주어가 없다. “令”을 빼야 “许多传统经济鱼类”가 주어가 된다.","fix":"由于长期过度捕捞和近海污染，渤海的许多传统经济鱼类几乎绝迹。","words":[["毕昇","Bì Shēng","비성(활자 인쇄 발명가)"],["演化","yǎnhuà","진화하다"],["捕捞","bǔlāo","어획하다"],["渤海","Bó Hǎi","보하이해"],["绝迹","juéjì","자취를 감추다"],["悬索桥","xuánsuǒqiáo","현수교"],["锚碇","máodìng","앵커리지(케이블 고정부)"]],"tr":["현수교의 주케이블은 고강도 강선 수만 가닥으로 이루어지며, 양 끝은 거대한 앵커리지로 암반에 단단히 고정된다.","북송 때 비성이 활자 인쇄술을 발명했는데, 이는 유럽의 같은 기술보다 약 400년 앞선 것이다.","판다의 조상은 원래 육식 동물이었으나, 나중에 점차 대나무를 주식으로 하는 종으로 진화했다.","오랜 남획과 연안 오염 때문에 보하이해의 전통적인 주요 어종 상당수가 거의 자취를 감추었다."],"ow":[[["悬索桥","xuánsuǒqiáo","현수교"],["主缆","zhǔlǎn","주케이블"],["钢丝","gāngsī","강선"],["锚碇","máodìng","앵커리지(케이블 고정부)"],["岩体","yántǐ","암반"]],[["毕昇","Bì Shēng","비성"],["活字印刷术","huózì yìnshuāshù","활자 인쇄술"],["同类","tónglèi","같은 종류"]],[["祖先","zǔxiān","조상"],["演化","yǎnhuà","진화하다"],["物种","wùzhǒng","종"]],[["捕捞","bǔlāo","어획하다"],["近海","jìnhǎi","연안"],["渤海","Bó Hǎi","보하이해"],["绝迹","juéjì","자취를 감추다"]]]},{"o":["地热能是一种储量巨大的清洁能源，冰岛约九成的家庭供暖都依靠地热。","这项新规对于餐饮外卖行业中一次性塑料餐具的过度使用和随意丢弃现象。","唐代诗人王维的作品诗中有画、画中有诗，苏轼对此曾给予极高的评价。","蜜蜂通过特定的“舞蹈”向同伴传递蜜源的方向与距离，这一现象令生物学家着迷不已。"],"a":1,"type":"술어 결여","why":"“对于……现象” 뒤에 동사가 없어서 새 규정이 그 현상에 무엇을 했는지가 빠졌다.","fix":"这项新规对餐饮外卖行业中一次性塑料餐具的过度使用和随意丢弃现象作出了严格限制。","words":[["地热能","dìrènéng","지열 에너지"],["冰岛","Bīngdǎo","아이슬란드"],["一次性","yícìxìng","일회용의"],["丢弃","diūqì","내버리다"],["王维","Wáng Wéi","왕유(당대 시인)"],["苏轼","Sū Shì","소식(북송 문인)"],["蜜源","mìyuán","꿀이 나는 곳"]],"tr":["지열 에너지는 매장량이 매우 큰 청정에너지로, 아이슬란드 가정의 약 90%가 지열로 난방을 한다.","이번 새 규정은 배달 음식 업계에서 일회용 플라스틱 식기를 지나치게 쓰고 함부로 버리는 현상을 겨냥하고 있다.","당나라 시인 왕유의 작품은 시 속에 그림이 있고 그림 속에 시가 있다고 하며, 소식은 이를 매우 높이 평가했다.","꿀벌은 특정한 '춤'으로 동료에게 꿀이 있는 곳의 방향과 거리를 알려 주는데, 이 현상은 생물학자들을 매료시켰다."],"ow":[[["地热能","dìrènéng","지열 에너지"],["储量","chǔliàng","매장량"],["冰岛","Bīngdǎo","아이슬란드"],["供暖","gōngnuǎn","난방"]],[["一次性","yícìxìng","일회용의"],["餐具","cānjù","식기"],["丢弃","diūqì","내버리다"],["随意","suíyì","마음대로"]],[["王维","Wáng Wéi","왕유"],["苏轼","Sū Shì","소식"],["给予","jǐyǔ","주다"]],[["蜜源","mìyuán","꿀이 나는 곳"],["传递","chuándì","전달하다"],["着迷","zháomí","매료되다"]]]},{"o":["黄土高原沟壑纵横，水土流失严重，曾是世界上生态最为脆弱的地区之一。","宣纸质地绵韧、不易蛀蚀，素有“纸寿千年”之称，深受历代书画家的青睐。","为了让更多市民养成垃圾分类的习惯，社区工作人员利用周末在各个小区门口。","水约占成年人体重的百分之六十，因此及时补充水分对维持新陈代谢至关重要。"],"a":2,"type":"술어 결여","why":"“在各个小区门口” 뒤에 동사가 없어서 직원들이 무엇을 했는지가 빠졌다.","fix":"为了让更多市民养成垃圾分类的习惯，社区工作人员利用周末在各个小区门口进行宣传讲解。","words":[["沟壑纵横","gōuhè zònghéng","골짜기가 이리저리 나 있다"],["脆弱","cuìruò","취약하다"],["宣纸","xuānzhǐ","선지(서화용 종이)"],["绵韧","miánrèn","부드럽고 질기다"],["蛀蚀","zhùshí","좀먹다"],["青睐","qīnglài","호감, 총애"],["新陈代谢","xīnchén dàixiè","신진대사"]],"tr":["황토고원은 골짜기가 이리저리 나 있고 물과 흙의 유실이 심해, 한때 세계에서 생태가 가장 취약한 지역 가운데 하나였다.","선지는 부드럽고 질기며 좀이 잘 슬지 않아 예부터 '종이 수명 천 년'이라 불렸고, 역대 서화가들의 사랑을 받았다.","더 많은 시민이 쓰레기 분리 습관을 들이도록, 마을 직원들은 주말마다 각 단지 입구에서 홍보 활동을 했다.","물은 성인 체중의 약 60%를 차지하므로, 수분을 제때 보충하는 것은 신진대사를 유지하는 데 매우 중요하다."],"ow":[[["黄土高原","Huángtǔ Gāoyuán","황토고원"],["沟壑纵横","gōuhè zònghéng","골짜기가 이리저리 나 있다"],["水土流失","shuǐtǔ liúshī","토양 유실"],["脆弱","cuìruò","취약하다"]],[["宣纸","xuānzhǐ","선지"],["绵韧","miánrèn","부드럽고 질기다"],["蛀蚀","zhùshí","좀먹다"],["青睐","qīnglài","호감, 총애"]],[["垃圾分类","lājī fēnlèi","쓰레기 분리"],["社区","shèqū","지역 사회, 마을"],["小区","xiǎoqū","주택 단지"]],[["补充","bǔchōng","보충하다"],["新陈代谢","xīnchén dàixiè","신진대사"],["至关重要","zhì guān zhòngyào","매우 중요하다"]]]},{"o":["青藏铁路穿越了大片多年冻土区，被誉为“天路”，是世界上海拔最高的高原铁路。","预应力混凝土构件在投入使用前就被预先施加了压应力，因而能够推迟受拉区裂缝的出现。","社交媒体上的碎片化阅读虽然便捷，却容易削弱人们进行深度思考的能力。","近年来，我国在风力发电与光伏发电领域的装机规模和技术水平，在全球范围内。"],"a":3,"type":"술어 결여","why":"주어 “装机规模和技术水平” 뒤에 “在全球范围内”만 있고 술어가 없다.","fix":"近年来，我国在风力发电与光伏发电领域的装机规模和技术水平，在全球范围内均名列前茅。","words":[["冻土","dòngtǔ","동토"],["碎片化","suìpiànhuà","파편화된"],["削弱","xuēruò","약화시키다"],["光伏","guāngfú","태양광 발전"],["预应力","yùyìnglì","프리스트레스(미리 준 힘)"],["构件","gòujiàn","부재, 구조 부품"],["便捷","biànjié","간편하다"]],"tr":["칭짱 철도는 넓은 영구 동토 지대를 지나며 '하늘길'로 불리고, 세계에서 가장 높은 곳을 달리는 고원 철도이다.","프리스트레스트 콘크리트 부재는 쓰이기 전에 미리 압축력을 받아 두기 때문에, 당기는 힘을 받는 부분의 균열을 늦출 수 있다.","소셜 미디어의 파편화된 읽기는 편리하지만, 사람들이 깊이 생각하는 능력을 약하게 만들기 쉽다.","최근 몇 년 사이 중국의 풍력·태양광 발전 설비 규모와 기술 수준은 세계적으로 앞서 있다."],"ow":[[["青藏铁路","Qīng-Zàng Tiělù","칭짱 철도"],["冻土","dòngtǔ","동토"],["誉为","yùwéi","~로 칭송되다"],["海拔","hǎibá","해발"]],[["预应力","yùyìnglì","프리스트레스(미리 준 힘)"],["混凝土","hùnníngtǔ","콘크리트"],["构件","gòujiàn","부재"],["压应力","yāyìnglì","압축 응력"],["裂缝","lièfèng","균열"]],[["碎片化","suìpiànhuà","파편화된"],["便捷","biànjié","간편하다"],["削弱","xuēruò","약화시키다"]],[["光伏","guāngfú","태양광 발전"],["装机","zhuāngjī","발전 설비를 설치하다"],["规模","guīmó","규모"]]]},{"o":["这种新型海水淡化装置投入使用后，显著改善了海岛上长期依靠船只运送淡水的居民。","《齐民要术》是北魏贾思勰所著的农学著作，系统总结了黄河中下游地区的农业生产经验。","长期睡眠不足不仅会导致注意力下降，还可能增加罹患心血管疾病的风险。","大体积混凝土浇筑后内部会释放大量水化热，若降温措施不当，极易产生温度裂缝。"],"a":0,"type":"중심어 결여","why":"“改善了……居民” 은 말이 안 된다. 개선된 것은 주민이 아니라 주민의 “生活条件”인데 그 중심어가 빠졌다.","fix":"这种新型海水淡化装置投入使用后，显著改善了海岛上长期依靠船只运送淡水的居民的生活条件。","words":[["海水淡化","hǎishuǐ dànhuà","해수 담수화"],["齐民要术","Qímín Yàoshù","제민요술(북위 농서)"],["贾思勰","Jiǎ Sīxié","가사협"],["罹患","líhuàn","(병에) 걸리다"],["浇筑","jiāozhù","(콘크리트를) 타설하다"],["水化热","shuǐhuàrè","수화열"]],"tr":["이 새 해수 담수화 장치가 가동된 뒤, 오랫동안 배로 실어 온 민물에 기대던 섬 주민들의 생활이 크게 나아졌다.","『제민요술』은 북위의 가사협이 지은 농서로, 황허강 중·하류 지역의 농업 경험을 체계적으로 정리했다.","오랫동안 잠이 모자라면 집중력이 떨어질 뿐 아니라 심혈관 질환에 걸릴 위험도 커질 수 있다.","대형 콘크리트를 부은 뒤에는 내부에서 수화열이 많이 나오는데, 식히는 방법이 적절하지 않으면 온도 균열이 생기기 쉽다."],"ow":[[["海水淡化","hǎishuǐ dànhuà","해수 담수화"],["装置","zhuāngzhì","장치"],["显著","xiǎnzhù","두드러지다"],["淡水","dànshuǐ","민물"]],[["齐民要术","Qímín Yàoshù","제민요술"],["北魏","Běi Wèi","북위"],["贾思勰","Jiǎ Sīxié","가사협"],["著作","zhùzuò","저서"]],[["注意力","zhùyìlì","집중력"],["罹患","líhuàn","(병에) 걸리다"],["心血管","xīnxuèguǎn","심혈관"]],[["混凝土","hùnníngtǔ","콘크리트"],["浇筑","jiāozhù","타설하다"],["水化热","shuǐhuàrè","수화열"],["裂缝","lièfèng","균열"]]]},{"o":["装配式建筑的墙板、楼梯等构件在工厂里批量生产，运到现场后像搭积木一样拼装起来。","科学家通过分析南极冰芯中的气泡，获得了过去八十万年间大气中二氧化碳浓度不断起伏变化的。","在建筑物底部设置橡胶隔震支座，能够显著减少地震能量向上部结构的传递。","人们在做决定时往往会被最先获得的信息所左右，心理学上称之为“锚定效应”。"],"a":1,"type":"중심어 결여","why":"“获得了……变化的” 뒤에 얻은 대상인 명사(“记录”)가 없다.","fix":"科学家通过分析南极冰芯中的气泡，获得了过去八十万年间大气中二氧化碳浓度不断起伏变化的珍贵记录。","words":[["冰芯","bīngxīn","빙하 코어"],["起伏","qǐfú","오르내리다"],["左右","zuǒyòu","좌우하다"],["锚定效应","máodìng xiàoyìng","앵커링 효과"],["装配式","zhuāngpèishì","조립식"],["隔震支座","gézhèn zhīzuò","면진 받침"]],"tr":["조립식 건축은 벽판·계단 같은 부재를 공장에서 대량으로 만들고, 현장에 옮겨 블록 쌓듯 조립한다.","과학자들은 남극 빙하 코어 속 기포를 분석해, 지난 80만 년 동안 대기 중 이산화탄소 농도가 오르내린 기록을 얻었다.","건물 바닥에 고무 면진 받침을 설치하면 지진 에너지가 위쪽 구조로 전달되는 것을 크게 줄일 수 있다.","사람은 결정을 내릴 때 처음 얻은 정보에 휘둘리기 쉬운데, 심리학에서는 이를 '앵커링 효과'라고 한다."],"ow":[[["装配式","zhuāngpèishì","조립식"],["构件","gòujiàn","부재"],["批量","pīliàng","대량으로"],["拼装","pīnzhuāng","조립하다"]],[["冰芯","bīngxīn","빙하 코어"],["气泡","qìpào","기포"],["浓度","nóngdù","농도"],["起伏","qǐfú","오르내리다"]],[["橡胶","xiàngjiāo","고무"],["隔震支座","gézhèn zhīzuò","면진 받침"],["显著","xiǎnzhù","두드러지게"]],[["左右","zuǒyòu","좌우하다"],["锚定效应","máodìng xiàoyìng","앵커링 효과"]]]},{"o":["云南西双版纳是我国热带雨林保存最完好的地区之一，孕育了极为丰富的动植物资源。","宋代瓷器以汝、官、哥、钧、定五大名窑最负盛名，其精湛的烧制工艺令后世叹为观止。","这家企业研发的可降解材料，有效缓解了长期以来塑料垃圾难以处理并严重污染土壤和水源，受到环保人士的好评。","古希腊哲学家亚里士多德认为，人天生是社会性的动物，离开城邦便无法过上完满的生活。"],"a":2,"type":"중심어 결여","why":"“缓解了……污染土壤和水源” 뒤에 완화한 대상인 “的问题”가 빠졌다.","fix":"这家企业研发的可降解材料，有效缓解了长期以来塑料垃圾难以处理并严重污染土壤和水源的问题，受到环保人士的好评。","words":[["西双版纳","Xīshuāngbǎnnà","시솽반나"],["孕育","yùnyù","길러 내다"],["窑","yáo","가마"],["精湛","jīngzhàn","정교하고 뛰어나다"],["叹为观止","tàn wéi guān zhǐ","감탄을 금치 못하다"],["可降解","kějiàngjiě","분해 가능한"],["亚里士多德","Yàlǐshìduōdé","아리스토텔레스"],["城邦","chéngbāng","도시 국가"]],"tr":["윈난 시솽반나는 중국에서 열대 우림이 가장 잘 보존된 지역 가운데 하나로, 매우 풍부한 동식물 자원을 길러 냈다.","송나라 도자기는 여요·관요·가요·균요·정요의 5대 명요가 가장 유명하며, 그 정교한 굽는 기술은 후대를 감탄하게 했다.","이 기업이 개발한 분해 가능 소재는 플라스틱 쓰레기가 처리하기 어렵고 흙과 물을 심하게 오염시키던 오랜 문제를 효과적으로 덜어 주어 환경 운동가들의 호평을 받았다.","고대 그리스 철학자 아리스토텔레스는 인간이 본래 사회적 동물이어서 도시 국가를 떠나면 온전한 삶을 살 수 없다고 보았다."],"ow":[[["西双版纳","Xīshuāngbǎnnà","시솽반나"],["热带雨林","rèdài yǔlín","열대 우림"],["孕育","yùnyù","길러 내다"]],[["名窑","míngyáo","이름난 가마"],["最负盛名","zuì fù shèngmíng","가장 유명하다"],["精湛","jīngzhàn","정교하고 뛰어나다"],["叹为观止","tàn wéi guān zhǐ","감탄을 금치 못하다"]],[["可降解","kě jiàngjiě","분해 가능한"],["缓解","huǎnjiě","완화하다"],["水源","shuǐyuán","수원"]],[["亚里士多德","Yàlǐshìduōdé","아리스토텔레스"],["天生","tiānshēng","타고나다"],["城邦","chéngbāng","도시 국가"]]]}],[{"o":["内蒙古库布其沙漠经过三十年的治理，已有三分之一的沙化土地重新披上了绿装。","一些超高层建筑在顶部悬挂了重达数百吨的阻尼器，用来减弱大风引起的楼体晃动。","一只成年座头鲸每天要吞食将近一吨半左右的磷虾和小鱼，才能维持其庞大身躯的能量消耗。","人的短时记忆容量十分有限，一般只能同时保持七个左右的信息单元。"],"a":2,"type":"어림수 중복","why":"“将近”과 “左右”가 둘 다 대략을 나타내어 겹친다. 하나만 써야 한다.","fix":"一只成年座头鲸每天要吞食将近一吨半的磷虾和小鱼，才能维持其庞大身躯的能量消耗。","words":[["库布其","Kùbùqí","쿠부치(사막)"],["沙化","shāhuà","사막화되다"],["座头鲸","zuòtóujīng","혹등고래"],["磷虾","línxiā","크릴"],["庞大","pángdà","거대하다"],["超高层","chāogāocéng","초고층"],["阻尼器","zǔníqì","댐퍼(진동 감쇠 장치)"]],"tr":["내몽골 쿠부치 사막은 30년 동안 가꾼 끝에, 사막화된 땅의 3분의 1이 다시 푸른 옷을 입게 되었다.","일부 초고층 건물은 꼭대기에 수백 톤에 이르는 댐퍼를 매달아, 강풍으로 생기는 건물의 흔들림을 줄인다.","다 자란 혹등고래 한 마리는 하루에 크릴과 작은 물고기를 1.5톤 가까이 먹어야 거대한 몸의 에너지 소모를 감당할 수 있다.","사람의 단기 기억 용량은 매우 한정되어 있어서, 보통 한 번에 정보 단위 일곱 개 정도만 붙잡아 둘 수 있다."],"ow":[[["库布其","Kùbùqí","쿠부치(사막)"],["治理","zhìlǐ","다스리다, 정비하다"],["沙化","shāhuà","사막화되다"]],[["超高层","chāogāocéng","초고층"],["悬挂","xuánguà","매달다"],["阻尼器","zǔníqì","댐퍼(진동 감쇠 장치)"],["晃动","huàngdòng","흔들리다"]],[["座头鲸","zuòtóujīng","혹등고래"],["吞食","tūnshí","삼키다"],["磷虾","línxiā","크릴"],["庞大","pángdà","거대하다"]],[["短时记忆","duǎnshí jìyì","단기 기억"],["容量","róngliàng","용량"]]]},{"o":["据估算，全球每年约有八百万吨上下的塑料垃圾流入海洋，对海洋生物构成严重威胁。","“海绵城市”通过透水铺装、下沉式绿地等设施，让城市在降雨时能够吸水、蓄水和渗水。","大跨度桥梁在设计阶段通常要按比例制作模型进行风洞试验，以检验其抗风性能。","研究发现，每天坚持步行三十分钟以上的人，患二型糖尿病的风险明显低于久坐少动的人。"],"a":0,"type":"어림수 중복","why":"“约”와 “上下”가 둘 다 대략을 나타내어 겹친다.","fix":"据估算，全球每年约有八百万吨塑料垃圾流入海洋，对海洋生物构成严重威胁。","words":[["透水","tòushuǐ","물이 스며 통하다"],["下沉式","xiàchénshì","아래로 꺼진 형태의"],["渗水","shènshuǐ","물이 스며들다"],["跨度","kuàdù","경간, 스팬"],["风洞","fēngdòng","풍동"],["糖尿病","tángniàobìng","당뇨병"]],"tr":["추산에 따르면 해마다 약 800만 톤의 플라스틱 쓰레기가 바다로 흘러들어 해양 생물을 심각하게 위협하고 있다.","'스펀지 도시'는 투수성 포장, 움푹 낮춘 녹지 같은 시설을 통해 비가 올 때 도시가 물을 빨아들이고 모으고 땅에 스며들게 한다.","경간이 긴 다리는 설계 단계에서 보통 축소 모형을 만들어 풍동 시험을 하고 바람에 견디는 성능을 검사한다.","연구에 따르면 매일 30분 이상 꾸준히 걷는 사람은 오래 앉아 덜 움직이는 사람보다 제2형 당뇨병에 걸릴 위험이 확실히 낮다."],"ow":[[["估算","gūsuàn","추산하다"],["构成","gòuchéng","이루다, 되다"],["威胁","wēixié","위협"]],[["透水","tòushuǐ","물이 스며 통하다"],["铺装","pūzhuāng","포장"],["下沉式","xiàchénshì","아래로 꺼진 형태의"],["蓄水","xùshuǐ","물을 모으다"],["渗水","shènshuǐ","물이 스며들다"]],[["跨度","kuàdù","경간, 스팬"],["比例","bǐlì","비율"],["风洞","fēngdòng","풍동"],["检验","jiǎnyàn","검사하다"]],[["糖尿病","tángniàobìng","당뇨병"],["久坐","jiǔzuò","오래 앉아 있다"]]]},{"o":["三江源地区是长江、黄河和澜沧江的发源地，素有“中华水塔”之美誉。","在淤泥深厚的软土地区建高楼，往往需要把钢筋混凝土桩打入地下数十米深的持力层。","北极熊依赖海冰捕食海豹，海冰面积的缩小直接威胁着它们的生存。","受地形与季风的共同影响，同处一省的这两座城市在年降水量上存在着十分悬殊的差别。"],"a":3,"type":"단어 안의 뜻 반복","why":"“悬殊”가 이미 ‘차이가 크다’는 뜻이라 “悬殊的差别”는 뜻이 겹친다.","fix":"受地形与季风的共同影响，同处一省的这两座城市年降水量相差十分悬殊。","words":[["三江源","Sānjiāngyuán","싼장위안(세 강의 발원지)"],["澜沧江","Láncāng Jiāng","란창강(메콩강 상류)"],["美誉","měiyù","명성, 좋은 이름"],["海豹","hǎibào","물범"],["悬殊","xuánshū","차이가 매우 크다"],["淤泥","yūní","진흙, 개흙"],["持力层","chílìcéng","지지층"]],"tr":["싼장위안 지역은 창장·황허·란창강의 발원지로, 예부터 '중국의 물탱크'라는 이름으로 불렸다.","진흙층이 두꺼운 연약 지반에 고층 건물을 지을 때는 철근 콘크리트 말뚝을 땅속 수십 미터 깊이의 지지층까지 박아야 하는 경우가 많다.","북극곰은 해빙에 의지해 물범을 사냥하므로, 해빙 면적이 줄어드는 것은 곧바로 그들의 생존을 위협한다.","지형과 계절풍의 영향을 함께 받아, 같은 성에 있는 이 두 도시는 연 강수량 차이가 매우 크다."],"ow":[[["三江源","Sānjiāngyuán","싼장위안"],["澜沧江","Láncāng Jiāng","란창강"],["发源地","fāyuándì","발원지"],["美誉","měiyù","좋은 이름, 명성"]],[["淤泥","yūní","진흙"],["钢筋","gāngjīn","철근"],["混凝土","hùnníngtǔ","콘크리트"],["桩","zhuāng","말뚝"],["持力层","chílìcéng","지지층"]],[["依赖","yīlài","의지하다"],["捕食","bǔshí","사냥하다"],["海豹","hǎibào","물범"]],[["季风","jìfēng","계절풍"],["降水量","jiàngshuǐliàng","강수량"],["悬殊","xuánshū","차이가 매우 크다"]]]},{"o":["王羲之的《兰亭集序》被后人誉为“天下第一行书”，其笔法飘逸灵动，变化无穷。","推行垃圾强制分类的主要目的是为了提高资源回收利用率，减少填埋和焚烧带来的污染。","开挖深基坑时，施工方常先在四周修筑地下连续墙，以防止周边土体坍塌和地下水涌入。","古人常用“春雨贵如油”来形容北方春季降水的稀少，以及它对越冬作物返青的重要意义。"],"a":1,"type":"단어 안의 뜻 반복","why":"“目的是”와 “为了”가 둘 다 목적을 나타내어 겹친다.","fix":"推行垃圾强制分类的主要目的是提高资源回收利用率，减少填埋和焚烧带来的污染。","words":[["王羲之","Wáng Xīzhī","왕희지"],["兰亭集序","Lántíng Jí Xù","난정집서"],["飘逸","piāoyì","자유분방하고 시원스럽다"],["填埋","tiánmái","매립하다"],["返青","fǎnqīng","(겨울을 난 작물이) 다시 푸르러지다"],["基坑","jīkēng","기초 굴착 구덩이"],["坍塌","tāntā","무너지다"]],"tr":["왕희지의 『난정집서』는 후대에 '천하제일 행서'로 칭송되며, 붓놀림이 자유롭고 생동감 있으며 변화가 끝이 없다.","쓰레기 분리를 의무화하는 주된 목적은 자원 재활용률을 높이고 매립과 소각에서 오는 오염을 줄이는 것이다.","깊은 기초 구덩이를 팔 때는 보통 먼저 사방에 지하 연속벽을 세워 주변 흙이 무너지거나 지하수가 밀려드는 것을 막는다.","옛사람들은 '봄비는 기름처럼 귀하다'는 말로 북방의 봄비가 드물다는 것과, 그 비가 겨울을 난 작물이 다시 푸르러지는 데 얼마나 중요한지를 나타냈다."],"ow":[[["王羲之","Wáng Xīzhī","왕희지"],["兰亭集序","Lántíng Jí Xù","난정집서"],["行书","xíngshū","행서"],["飘逸","piāoyì","자유분방하다"]],[["推行","tuīxíng","추진하다"],["回收","huíshōu","회수하다"],["填埋","tiánmái","매립하다"],["焚烧","fénshāo","소각하다"]],[["基坑","jīkēng","기초 굴착 구덩이"],["修筑","xiūzhù","축조하다"],["坍塌","tāntā","무너지다"],["涌入","yǒngrù","밀려들다"]],[["春雨贵如油","chūnyǔ guì rú yóu","봄비는 기름처럼 귀하다"],["越冬","yuèdōng","겨울을 나다"],["返青","fǎnqīng","다시 푸르러지다"]]]},{"o":["竺可桢毕生一辈子致力于我国气象与物候学研究，为后人留下了大量宝贵的观测资料。","敦煌的月牙泉被鸣沙山环抱，千百年来始终未被流沙掩埋，实为大自然的一大奇观。","蒙古族的长调民歌旋律悠长、节奏自由，已被联合国教科文组织列入人类非物质文化遗产名录。","在富含地下水的松散地层中修建隧道时，工程师有时会先用冷冻法把周围的土体冻成坚硬的“冰墙”。"],"a":0,"type":"단어 안의 뜻 반복","why":"“毕生”이 이미 ‘평생’이라는 뜻이라 “一辈子”와 겹친다.","fix":"竺可桢毕生致力于我国气象与物候学研究，为后人留下了大量宝贵的观测资料。","words":[["竺可桢","Zhú Kězhēn","주커전(기상학자)"],["毕生","bìshēng","평생"],["物候学","wùhòuxué","생물계절학"],["鸣沙山","Míngshā Shān","밍사산"],["月牙泉","Yuèyá Quán","웨야취안(초승달 샘)"],["掩埋","yǎnmái","파묻다"],["长调","chángdiào","(몽골) 장조 민요"],["地层","dìcéng","지층"]],"tr":["주커전은 평생을 중국 기상학과 생물계절학 연구에 바쳐, 후대에 귀중한 관측 자료를 많이 남겼다.","둔황의 웨야취안은 밍사산에 둘러싸여 있는데도 천백 년 동안 모래에 묻히지 않아, 참으로 자연의 큰 경이라 할 만하다.","몽골족의 장조 민요는 가락이 길고 박자가 자유로우며, 유네스코 인류무형문화유산 목록에 올랐다.","지하수가 많은 무른 지층에 터널을 뚫을 때, 기술자들은 때로 먼저 냉동 공법으로 주변 흙을 얼려 단단한 '얼음벽'을 만든다."],"ow":[[["竺可桢","Zhú Kězhēn","주커전"],["毕生","bìshēng","평생"],["致力于","zhìlì yú","~에 힘쓰다"],["物候学","wùhòuxué","생물계절학"]],[["月牙泉","Yuèyá Quán","웨야취안"],["鸣沙山","Míngshā Shān","밍사산"],["环抱","huánbào","둘러싸다"],["掩埋","yǎnmái","파묻다"],["奇观","qíguān","기이한 경관"]],[["长调","chángdiào","(몽골) 장조 민요"],["旋律","xuánlǜ","선율"],["悠长","yōucháng","길다"],["非物质文化遗产","fēiwùzhì wénhuà yíchǎn","무형 문화유산"]],[["松散","sōngsǎn","느슨하다, 무르다"],["地层","dìcéng","지층"],["冷冻","lěngdòng","냉동하다"],["坚硬","jiānyìng","단단하다"]]]},{"o":["南方喀斯特地貌以石林、溶洞和峰丛为典型代表，景观奇特，吸引了大批中外游客。","新奥法强调充分利用围岩自身的自承能力，在开挖后及时喷射混凝土加以支护。","有专家指出，部分城市在规划绿地时过于太注重观赏效果，而忽视了本土植物的生态功能。","人的情绪具有传染性，长时间与消极的人相处，自己也容易变得悲观失望。"],"a":2,"type":"단어 안의 뜻 반복","why":"“过于”와 “太”가 둘 다 ‘지나치게’라는 뜻이라 겹친다.","fix":"有专家指出，部分城市在规划绿地时过于注重观赏效果，而忽视了本土植物的生态功能。","words":[["喀斯特","kāsītè","카르스트"],["溶洞","róngdòng","석회 동굴"],["峰丛","fēngcóng","봉우리 무리"],["本土","běntǔ","토착의, 현지의"],["传染性","chuánrǎnxìng","전염성"],["围岩","wéiyán","(터널 주변의) 암반"],["支护","zhīhù","지보하다(받쳐 보강하다)"]],"tr":["남방의 카르스트 지형은 석림·석회 동굴·봉우리 무리가 대표적이며, 경관이 독특해 국내외 관광객을 많이 끌어들였다.","NATM 공법은 주변 암반이 스스로 버티는 힘을 최대한 활용하고, 굴착한 뒤 곧바로 콘크리트를 뿜어 붙여 지보한다.","일부 도시는 녹지를 계획할 때 보기 좋은 효과에만 지나치게 신경 쓰고 토종 식물의 생태적 기능은 소홀히 한다고 전문가들은 지적한다.","사람의 감정은 전염성이 있어서, 부정적인 사람과 오래 함께 지내면 자신도 비관하고 실망하기 쉽다."],"ow":[[["喀斯特","kāsītè","카르스트"],["地貌","dìmào","지형"],["溶洞","róngdòng","석회 동굴"],["峰丛","fēngcóng","봉우리 무리"]],[["新奥法","xīn'àofǎ","NATM(신오스트리아 터널 공법)"],["围岩","wéiyán","주변 암반"],["喷射","pēnshè","분사하다"],["支护","zhīhù","지보하다"]],[["规划","guīhuà","계획하다"],["观赏","guānshǎng","감상하다"],["忽视","hūshì","소홀히 하다"],["本土","běntǔ","토착의"]],[["传染性","chuánrǎnxìng","전염성"],["消极","xiāojí","부정적인"],["悲观","bēiguān","비관적이다"]]]},{"o":["大跨径桥梁多采用钢箱梁，这种中空的箱形结构既能减轻自重，又具有很强的抗扭能力。","钢结构建筑自重轻、延性好，在地震中能通过自身的变形吸收大量能量。","柳宗元被贬永州期间写下了《永州八记》，开创了中国山水游记的新境界。","近十年来，这座城市的光伏产业园区里不断涌现出一大批新兴企业相继出现。"],"a":3,"type":"단어 안의 뜻 반복","why":"“涌现”이 이미 ‘대량으로 나타나다’는 뜻이라 뒤의 “相继出现”와 겹친다.","fix":"近十年来，这座城市的光伏产业园区里不断涌现出一大批新兴企业。","words":[["柳宗元","Liǔ Zōngyuán","유종원"],["贬","biǎn","좌천되다"],["涌现","yǒngxiàn","대량으로 나타나다"],["钢箱梁","gāngxiāngliáng","강상형 거더"],["抗扭","kàngniǔ","비틀림에 견디다"],["延性","yánxìng","연성"]],"tr":["경간이 긴 다리에는 강상형 거더가 많이 쓰이는데, 속이 빈 상자 모양 구조라 무게를 줄이면서도 비틀림에 강하다.","철골 구조 건물은 무게가 가볍고 연성이 좋아, 지진 때 스스로 변형되면서 많은 에너지를 흡수할 수 있다.","유종원은 융저우로 좌천된 동안 『영주팔기』를 써서 중국 산수 기행문의 새 경지를 열었다.","최근 10년 사이 이 도시의 태양광 산업 단지에는 새로운 기업이 대거 잇따라 생겨났다."],"ow":[[["跨径","kuàjìng","경간"],["钢箱梁","gāngxiāngliáng","강상형 거더"],["中空","zhōngkōng","속이 비다"],["抗扭","kàngniǔ","비틀림에 견디다"]],[["钢结构","gāngjiégòu","철골 구조"],["自重","zìzhòng","자체 무게"],["延性","yánxìng","연성"],["变形","biànxíng","변형되다"]],[["柳宗元","Liǔ Zōngyuán","유종원"],["贬","biǎn","좌천되다"],["永州","Yǒngzhōu","융저우"],["游记","yóujì","기행문"],["境界","jìngjiè","경지"]],[["光伏","guāngfú","태양광 발전"],["涌现","yǒngxiàn","대량으로 나타나다"],["新兴","xīnxīng","신흥의"],["相继","xiāngjì","잇따라"]]]},{"o":["青海湖是我国最大的内陆咸水湖，每年春夏之交都有大批候鸟飞来此处繁衍后代。","凡是进入自然保护区核心区的所有人员，都必须事先获得管理部门的书面批准。","架桥机能将上百吨重的预制箱梁精准地吊放到桥墩上，大大加快了高架桥的建设速度。","咖啡因能够刺激中枢神经，但大量摄入难免会引起心悸、失眠等不良反应。"],"a":1,"type":"기타 군더더기","why":"“凡是”가 이미 ‘모든’이라는 뜻이라 “所有”와 겹친다.","fix":"凡是进入自然保护区核心区的人员，都必须事先获得管理部门的书面批准。","words":[["青海湖","Qīnghǎi Hú","칭하이호"],["候鸟","hòuniǎo","철새"],["繁衍","fányǎn","번식하다"],["中枢神经","zhōngshū shénjīng","중추 신경"],["心悸","xīnjì","가슴 두근거림"],["架桥机","jiàqiáojī","교량 가설기"],["桥墩","qiáodūn","교각"]],"tr":["칭하이호는 중국에서 가장 큰 내륙 염호로, 해마다 봄과 여름 사이에 많은 철새가 날아와 새끼를 친다.","자연 보호 구역의 핵심 구역에 들어가는 모든 사람은 반드시 미리 관리 기관의 서면 허가를 받아야 한다.","교량 가설기는 100톤이 넘는 프리캐스트 상자형 보를 교각 위에 정확히 올려놓아 고가교 건설 속도를 크게 높였다.","카페인은 중추 신경을 자극하지만, 많이 섭취하면 가슴 두근거림·불면 같은 부작용이 생기기 마련이다."],"ow":[[["青海湖","Qīnghǎi Hú","칭하이호"],["咸水湖","xiánshuǐhú","염호"],["候鸟","hòuniǎo","철새"],["繁衍","fányǎn","번식하다"]],[["凡是","fánshì","무릇, 모든"],["核心区","héxīnqū","핵심 구역"],["事先","shìxiān","사전에"],["批准","pīzhǔn","허가"]],[["架桥机","jiàqiáojī","교량 가설기"],["预制","yùzhì","미리 제작하다"],["桥墩","qiáodūn","교각"],["高架桥","gāojiàqiáo","고가교"]],[["咖啡因","kāfēiyīn","카페인"],["中枢神经","zhōngshū shénjīng","중추 신경"],["摄入","shèrù","섭취하다"],["难免","nánmiǎn","~하기 마련이다"],["心悸","xīnjì","가슴 두근거림"]]]},{"o":["屠呦呦受东晋葛洪《肘后备急方》的启发，改用低温方法提取，最终成功获得了青蒿素。","草原上的狼通过捕食病弱的黄羊和野兔，在客观上维持了草原生态系统的平衡。","民间剪纸题材广泛，构图夸张，常常寄托着人们对美好生活的向往。","历经三年的抢修加固，这座始建于明代的城隍庙将于明年春季再次重新向公众开放。"],"a":3,"type":"기타 군더더기","why":"“再次”와 “重新”이 둘 다 ‘다시’라는 뜻이라 겹친다.","fix":"历经三年的抢修加固，这座始建于明代的城隍庙将于明年春季重新向公众开放。","words":[["屠呦呦","Tú Yōuyōu","투유유"],["葛洪","Gě Hóng","갈홍"],["肘后备急方","Zhǒuhòu Bèijí Fāng","주후비급방"],["青蒿素","qīnghāosù","아르테미시닌"],["黄羊","huángyáng","몽골가젤"],["寄托","jìtuō","(마음을) 담다"],["抢修","qiǎngxiū","긴급 수리하다"],["城隍庙","chénghuángmiào","성황묘"]],"tr":["투유유는 동진 갈홍의 『주후비급방』에서 실마리를 얻어 저온 추출 방식으로 바꾸었고, 마침내 아르테미시닌을 얻는 데 성공했다.","초원의 늑대는 병들고 약한 몽골가젤과 산토끼를 잡아먹음으로써 결과적으로 초원 생태계의 균형을 지켜 왔다.","민간 전지 공예는 소재가 폭넓고 구도가 과장되어 있으며, 흔히 더 나은 삶에 대한 사람들의 바람을 담고 있다.","3년에 걸친 긴급 보수와 보강을 거쳐, 명나라 때 처음 지은 이 성황묘가 내년 봄 다시 일반에 개방된다."],"ow":[[["屠呦呦","Tú Yōuyōu","투유유"],["葛洪","Gě Hóng","갈홍"],["肘后备急方","Zhǒuhòu Bèijí Fāng","주후비급방"],["提取","tíqǔ","추출하다"],["青蒿素","qīnghāosù","아르테미시닌"]],[["捕食","bǔshí","잡아먹다"],["黄羊","huángyáng","몽골가젤"],["客观上","kèguān shang","객관적으로, 결과적으로"]],[["剪纸","jiǎnzhǐ","전지(종이 오리기)"],["题材","tícái","소재"],["构图","gòutú","구도"],["寄托","jìtuō","(마음을) 담다"]],[["抢修","qiǎngxiū","긴급 수리하다"],["加固","jiāgù","보강하다"],["城隍庙","chénghuángmiào","성황묘"]]]},{"o":["对于沿海地区频发的赤潮现象，对此海洋部门已经建立起了一套完善的监测预警机制。","徽派建筑以白墙黛瓦、马头墙为主要特色，与周围的山水田园浑然一体。","美国心理学家马斯洛将人的需要由低到高分为五个层次，自我实现位于最高层。","竹子是世界上生长最快的植物之一，毛竹在生长旺季一昼夜能长高一米左右。"],"a":0,"type":"기타 군더더기","why":"앞에 “对于……现象”이 있는데 뒤에 또 “对此”를 써서 같은 대상을 두 번 가리킨다.","fix":"对于沿海地区频发的赤潮现象，海洋部门已经建立起了一套完善的监测预警机制。","words":[["赤潮","chìcháo","적조"],["预警","yùjǐng","조기 경보"],["徽派","Huīpài","후이저우 양식"],["黛瓦","dàiwǎ","검푸른 기와"],["马头墙","mǎtóuqiáng","마두장(계단식 방화벽)"],["浑然一体","hún rán yì tǐ","혼연일체"],["马斯洛","Mǎsīluò","매슬로"],["毛竹","máozhú","맹종죽"]],"tr":["연안 지역에서 자주 일어나는 적조에 대해 해양 당국은 이미 완비된 감시·조기 경보 체계를 세웠다.","후이저우 양식 건축은 흰 벽과 검푸른 기와, 마두장이 주된 특징이며 주변 산수·전원과 하나로 어우러진다.","미국 심리학자 매슬로는 인간의 욕구를 낮은 것에서 높은 것까지 다섯 단계로 나누었고, 자아실현을 가장 높은 단계에 두었다.","대나무는 세계에서 가장 빨리 자라는 식물 가운데 하나로, 맹종죽은 한창 자라는 시기에 하룻밤 낮 사이 1미터쯤 자란다."],"ow":[[["频发","pínfā","자주 발생하다"],["赤潮","chìcháo","적조"],["监测","jiāncè","감시하다"],["预警","yùjǐng","조기 경보"],["机制","jīzhì","체계"]],[["徽派","Huīpài","후이저우 양식"],["黛瓦","dàiwǎ","검푸른 기와"],["马头墙","mǎtóuqiáng","마두장(계단식 방화벽)"],["浑然一体","hún rán yì tǐ","혼연일체"]],[["马斯洛","Mǎsīluò","매슬로"],["层次","céngcì","단계"],["自我实现","zìwǒ shíxiàn","자아실현"]],[["毛竹","máozhú","맹종죽"],["旺季","wàngjì","한창때"],["一昼夜","yí zhòuyè","하루 밤낮"]]]}],[{"o":["为了不影响下方铁路的正常运行，这座立交桥采用了转体施工法，先在路旁浇筑桥身再整体旋转到位。","埋设在大坝坝体内的各类传感器，在及时发现结构损伤、预防溃坝事故等方面发扬着重要作用。","景德镇制瓷历史悠久，所产瓷器素以“白如玉、明如镜、薄如纸、声如磬”著称。","人们之所以容易高估小概率事件，是因为媒体对这类事件的报道往往格外密集。"],"a":1,"type":"동사–목적어","why":"“作用”은 “发挥”와 어울린다. “发扬”은 정신·전통 같은 것에 쓴다.","fix":"埋设在大坝坝体内的各类传感器，在及时发现结构损伤、预防溃坝事故等方面发挥着重要作用。","words":[["景德镇","Jǐngdézhèn","징더전"],["磬","qìng","경쇠(타악기)"],["高估","gāogū","과대평가하다"],["立交桥","lìjiāoqiáo","입체 교차로"],["转体","zhuǎntǐ","회전시키다(교량 회전 공법)"],["坝体","bàtǐ","댐 몸체"],["溃坝","kuìbà","댐 붕괴"]],"tr":["아래 철도 운행에 지장을 주지 않으려고 이 입체 교차로는 회전 공법을 썼다. 먼저 길옆에서 다리 몸체를 만든 뒤 통째로 돌려 제자리에 맞췄다.","댐 몸체 안에 묻어 둔 여러 센서는 구조 손상을 제때 찾아내고 댐 붕괴 사고를 막는 데 중요한 역할을 한다.","징더전은 도자기를 만든 역사가 길고, 그곳 도자기는 '옥처럼 희고 거울처럼 밝으며 종이처럼 얇고 경쇠 같은 소리가 난다'고 이름났다.","사람들이 확률이 낮은 사건을 쉽게 과대평가하는 것은 언론이 그런 사건을 유난히 집중적으로 보도하기 때문이다."],"ow":[[["立交桥","lìjiāoqiáo","입체 교차로"],["转体","zhuǎntǐ","회전시키다(교량 회전 공법)"],["浇筑","jiāozhù","타설하다"],["旋转","xuánzhuǎn","회전하다"]],[["坝体","bàtǐ","댐 몸체"],["传感器","chuángǎnqì","센서"],["损伤","sǔnshāng","손상"],["溃坝","kuìbà","댐 붕괴"]],[["景德镇","Jǐngdézhèn","징더전"],["悠久","yōujiǔ","유구하다"],["磬","qìng","경쇠"],["著称","zhùchēng","유명하다"]],[["高估","gāogū","과대평가하다"],["概率","gàilǜ","확률"],["密集","mìjí","밀집하다"]]]},{"o":["顶推法是在桥头逐段预制梁体，再用千斤顶将其向前推送，直至跨越整个河谷的施工方法。","冬季燃煤取暖排放的大量颗粒物，是造成华北地区雾霾天气的重要原因之一。","二〇二〇年，嫦娥五号探测器成功从月球采集并带回了一千七百多克月壤样品。","为了保护这片古老的胡杨林，当地严格控制了地下水的开采，并大力提高了周边农田的节水灌溉面积。"],"a":3,"type":"동사–목적어","why":"“面积”는 “扩大”와 어울리고 “提高”와는 어울리지 않는다.","fix":"为了保护这片古老的胡杨林，当地严格控制了地下水的开采，并大力扩大了周边农田的节水灌溉面积。","words":[["颗粒物","kēlìwù","미세 입자"],["雾霾","wùmái","스모그"],["嫦娥五号","Cháng'é Wǔ Hào","창어 5호"],["月壤","yuèrǎng","달 토양"],["胡杨林","húyánglín","후양(사막 포플러) 숲"],["顶推","dǐngtuī","밀어내기(압출) 공법"],["千斤顶","qiānjīndǐng","잭"]],"tr":["압출 공법은 다리 머리 쪽에서 보를 한 토막씩 만들고, 잭으로 앞으로 밀어 내 골짜기 전체를 건널 때까지 이어 가는 시공 방법이다.","겨울철 석탄 난방으로 배출되는 많은 미세 입자는 화베이 지역 스모그의 중요한 원인 가운데 하나다.","2020년 창어 5호 탐사선은 달에서 1,700여 그램의 토양 시료를 채취해 가져오는 데 성공했다.","이 오래된 후양 숲을 지키려고 그 지역은 지하수 개발을 엄격히 제한하고, 주변 농지의 절수 관개 면적을 크게 늘렸다."],"ow":[[["顶推法","dǐngtuīfǎ","압출 공법"],["预制","yùzhì","미리 제작하다"],["千斤顶","qiānjīndǐng","잭"],["河谷","hégǔ","하곡, 골짜기"]],[["燃煤","ránméi","석탄을 때다"],["颗粒物","kēlìwù","미세 입자"],["雾霾","wùmái","스모그"]],[["嫦娥五号","Cháng'é Wǔ Hào","창어 5호"],["探测器","tàncèqì","탐사선"],["采集","cǎijí","채취하다"],["月壤","yuèrǎng","달 토양"]],[["胡杨林","húyánglín","후양 숲"],["开采","kāicǎi","채굴하다, 퍼 올리다"],["灌溉","guàngài","관개하다"]]]},{"o":["这部纪录片通过大量珍贵的影像，展现了中华鲟艰难的洄游历程，极大地增强了公众保护长江生物多样性的水平。","据《后汉书》记载，东汉张衡发明的候风地动仪能够测知远方发生地震的大致方向。","建造超高层建筑时，需要用高压泵把混凝土输送到数百米高的作业面，这对泵送设备提出了极高的要求。","东北虎是现存体型最大的猫科动物，主要分布在中俄边境一带的温带森林中。"],"a":0,"type":"동사–목적어","why":"“增强”은 “意识”와 어울리고 “水平”과는 어울리지 않는다.","fix":"这部纪录片通过大量珍贵的影像，展现了中华鲟艰难的洄游历程，极大地增强了公众保护长江生物多样性的意识。","words":[["纪录片","jìlùpiàn","다큐멘터리"],["中华鲟","Zhōnghuáxún","중국철갑상어"],["洄游","huíyóu","회유하다"],["张衡","Zhāng Héng","장형"],["地动仪","dìdòngyí","지동의(지진계)"],["猫科","māokē","고양잇과"],["泵送","bèngsòng","펌프로 압송하다"],["作业面","zuòyèmiàn","작업면"]],"tr":["이 다큐멘터리는 귀한 영상을 많이 보여 주며 중국철갑상어의 고된 회유 과정을 그려 내, 창장 생물 다양성을 지키려는 대중의 의식을 크게 높였다.","『후한서』에 따르면 동한의 장형이 만든 후풍지동의는 먼 곳에서 일어난 지진의 대략적인 방향을 알아낼 수 있었다.","초고층 건물을 지을 때는 고압 펌프로 콘크리트를 수백 미터 높이의 작업면까지 보내야 해서, 펌프 장비에 아주 높은 수준이 요구된다.","시베리아호랑이는 현존하는 가장 큰 고양잇과 동물로, 주로 중국과 러시아 국경 일대의 온대 숲에 산다."],"ow":[[["纪录片","jìlùpiàn","다큐멘터리"],["中华鲟","Zhōnghuáxún","중국철갑상어"],["洄游","huíyóu","회유하다"],["生物多样性","shēngwù duōyàngxìng","생물 다양성"]],[["后汉书","Hòu Hàn Shū","후한서"],["张衡","Zhāng Héng","장형"],["地动仪","dìdòngyí","지동의(지진계)"]],[["超高层","chāogāocéng","초고층"],["混凝土","hùnníngtǔ","콘크리트"],["作业面","zuòyèmiàn","작업면"],["泵送","bèngsòng","펌프로 압송하다"]],[["东北虎","Dōngběihǔ","시베리아호랑이"],["猫科","māokē","고양잇과"],["温带","wēndài","온대"]]]},{"o":["端砚石质坚实温润，发墨快而不损笔毫，与徽墨、宣纸、湖笔同为文房珍品。","我国北方部分地区地下水长期超采，已形成了大面积的地下水漏斗区。","经过二十年的退耕还林，这一地区的森林覆盖率由不足百分之十提升到了百分之四十，空气质量也变得越来越清新。","根据心理学上的“首因效应”，人们对他人形成的第一印象往往会在很长时间内影响后续的判断。"],"a":2,"type":"주어–술어","why":"“清新”한 것은 “空气”이지 “空气质量”가 아니다. 주어와 술어가 맞지 않는다.","fix":"经过二十年的退耕还林，这一地区的森林覆盖率由不足百分之十提升到了百分之四十，空气也变得越来越清新。","words":[["端砚","duānyàn","단연(벼루)"],["温润","wēnrùn","따뜻하고 윤기 있다"],["徽墨","huīmò","휘묵(먹)"],["超采","chāocǎi","과다 채취하다"],["漏斗","lòudǒu","깔때기"],["退耕还林","tuì gēng huán lín","경작지를 숲으로 되돌리다"],["覆盖率","fùgàilǜ","피복률"],["首因效应","shǒuyīn xiàoyìng","초두 효과"]],"tr":["단연은 돌이 단단하면서도 매끄러워 먹이 잘 갈리고 붓털을 상하게 하지 않으며, 휘묵·선지·호필과 함께 문방의 보물로 꼽힌다.","중국 북방 일부 지역은 오랫동안 지하수를 지나치게 퍼 올려, 이미 넓은 지하수 깔때기 지대가 생겼다.","20년간 농지를 숲으로 되돌린 결과 이 지역의 숲 비율은 10% 미만에서 40%로 올랐고, 공기도 점점 맑아졌다.","심리학의 '초두 효과'에 따르면, 사람이 남에게 받은 첫인상은 오랫동안 이후 판단에 영향을 미치는 경우가 많다."],"ow":[[["端砚","duānyàn","단연(벼루)"],["温润","wēnrùn","따뜻하고 윤기 있다"],["徽墨","huīmò","휘묵"],["宣纸","xuānzhǐ","선지"],["珍品","zhēnpǐn","진품"]],[["超采","chāocǎi","과다 채취하다"],["漏斗","lòudǒu","깔때기"]],[["退耕还林","tuì gēng huán lín","경작지를 숲으로 되돌리다"],["覆盖率","fùgàilǜ","피복률"],["清新","qīngxīn","맑고 상쾌하다"]],[["首因效应","shǒuyīn xiàoyìng","초두 효과"],["印象","yìnxiàng","인상"],["后续","hòuxù","이후의"]]]},{"o":["北京香山的红叶以黄栌为主，其观赏期一般在每年十月中下旬最为艳丽。","建造数百米高的核心筒时，工人们使用液压爬模，让模板随着楼层升高而自动向上爬升。","王阳明主张“知行合一”，认为真正的知识必须在实践中加以检验。","生活在漆黑深海中的某些鱼类能够自身发光，借此诱捕猎物、迷惑天敌或与同伴交流。"],"a":0,"type":"주어–술어","why":"“艳丽”한 것은 잎 색이지 “观赏期”(관람 시기)가 아니다. 주어와 술어가 맞지 않는다.","fix":"北京香山的红叶以黄栌为主，其叶色一般在每年十月中下旬最为艳丽。","words":[["黄栌","huánglú","안개나무"],["艳丽","yànlì","화려하고 곱다"],["王阳明","Wáng Yángmíng","왕양명"],["知行合一","zhī xíng hé yī","지행합일"],["诱捕","yòubǔ","꾀어 잡다"],["天敌","tiāndí","천적"],["核心筒","héxīntǒng","코어 월(중심 구조체)"],["液压","yèyā","유압"]],"tr":["베이징 샹산의 단풍은 안개나무가 대부분이며, 해마다 10월 중하순에 가장 곱게 물든다.","수백 미터 높이의 코어 월을 지을 때 작업자들은 유압 클라이밍 폼을 써서, 층이 올라감에 따라 거푸집이 저절로 위로 올라가게 한다.","왕양명은 '지행합일'을 주장하며, 참된 지식은 반드시 실천 속에서 검증되어야 한다고 보았다.","캄캄한 심해에 사는 어떤 물고기는 스스로 빛을 내어, 이를 이용해 먹이를 꾀어 잡거나 천적을 속이거나 동료와 소통한다."],"ow":[[["香山","Xiāng Shān","샹산"],["黄栌","huánglú","안개나무"],["观赏期","guānshǎngqī","관람 시기"],["艳丽","yànlì","화려하고 곱다"]],[["核心筒","héxīntǒng","코어 월(중심 구조체)"],["液压","yèyā","유압"],["爬模","pámú","클라이밍 폼"],["模板","múbǎn","거푸집"]],[["王阳明","Wáng Yángmíng","왕양명"],["知行合一","zhī xíng hé yī","지행합일"],["检验","jiǎnyàn","검증하다"]],[["漆黑","qīhēi","칠흑같이 어둡다"],["诱捕","yòubǔ","꾀어 잡다"],["迷惑","míhuò","현혹하다"],["天敌","tiāndí","천적"]]]},{"o":["借助建筑信息模型，设计人员可以在开工前发现管线之间的碰撞问题，减少返工和浪费。","塞罕坝林场的建设者用半个多世纪的坚守，在高原荒漠上营造出了百万亩人工林海。","低辐射镀膜玻璃能够反射热辐射，在冬季减少室内热量散失，在夏季阻挡室外的热量。","白鹤滩水电站的全面投产发电，是我国继三峡工程之后又一项举世瞩目的超级工程。"],"a":3,"type":"주어–목적어","why":"“全面投产发电”(발전 시작)은 “超级工程”(공사)일 수 없다. 공사인 것은 “白鹤滩水电站”이다.","fix":"白鹤滩水电站是我国继三峡工程之后又一项举世瞩目的超级工程。","words":[["塞罕坝","Sàihǎnbà","싸이한바"],["坚守","jiānshǒu","굳게 지키다"],["白鹤滩","Báihètān","바이허탄"],["投产","tóuchǎn","생산에 들어가다"],["举世瞩目","jǔ shì zhǔ mù","온 세상이 주목하다"],["返工","fǎngōng","재작업하다"],["镀膜","dùmó","코팅막"],["散失","sànshī","흩어져 없어지다"]],"tr":["건축 정보 모델을 이용하면 설계자는 착공 전에 배관·배선끼리 부딪치는 문제를 찾아내 재작업과 낭비를 줄일 수 있다.","싸이한바 임장의 일꾼들은 반세기 넘게 버티며 고원의 황무지에 백만 무에 이르는 인공 숲을 일궈 냈다.","저방사 코팅 유리는 열복사를 반사해, 겨울에는 실내 열이 빠져나가는 것을 줄이고 여름에는 바깥 열을 막아 준다.","전면 가동에 들어간 바이허탄 수력 발전소는 싼샤 공사에 이어 세계가 주목하는 중국의 또 하나의 초대형 공사이다."],"ow":[[["借助","jièzhù","~의 도움을 빌리다"],["管线","guǎnxiàn","배관·배선"],["碰撞","pèngzhuàng","충돌"],["返工","fǎngōng","재작업하다"]],[["塞罕坝","Sàihǎnbà","싸이한바"],["坚守","jiānshǒu","굳게 지키다"],["荒漠","huāngmò","황무지"],["营造","yíngzào","조성하다"]],[["辐射","fúshè","복사"],["镀膜","dùmó","코팅막"],["散失","sànshī","흩어져 없어지다"],["阻挡","zǔdǎng","막다"]],[["白鹤滩","Báihètān","바이허탄"],["投产","tóuchǎn","생산에 들어가다"],["三峡","Sānxiá","싼샤"],["举世瞩目","jǔ shì zhǔ mù","온 세상이 주목하다"]]]},{"o":["气候变化导致的海平面上升，正威胁着马尔代夫等低海拔岛国的生存。","位于河西走廊西端的敦煌，曾是丝绸之路上东西方文化交流最为繁盛的历史时期。","海带、紫菜等藻类富含碘元素，适量食用有助于预防甲状腺肿大。","圆明园曾被誉为“万园之园”，其建筑融汇了中国传统园林与西洋建筑的风格。"],"a":1,"type":"주어–목적어","why":"주어 “敦煌”은 장소인데 “是……历史时期”라고 해서 장소가 시기가 되어 버렸다.","fix":"位于河西走廊西端的敦煌，曾是丝绸之路上东西方文化交流的重要枢纽。","words":[["海平面","hǎipíngmiàn","해수면"],["马尔代夫","Mǎ'ěrdàifū","몰디브"],["河西走廊","Héxī Zǒuláng","허시 회랑"],["繁盛","fánshèng","번성하다"],["碘","diǎn","요오드"],["甲状腺","jiǎzhuàngxiàn","갑상선"],["融汇","rónghuì","융합하다"]],"tr":["기후 변화로 해수면이 높아지면서 몰디브 같은 낮은 섬나라들의 생존이 위협받고 있다.","허시 회랑 서쪽 끝의 둔황은 한때 실크로드에서 동서 문화 교류가 가장 활발했던 곳이었다.","다시마·김 같은 해조류는 요오드가 풍부해, 알맞게 먹으면 갑상선이 붓는 것을 막는 데 도움이 된다.","원명원은 한때 '정원 중의 정원'으로 불렸으며, 그 건축은 중국 전통 정원과 서양 건축의 양식을 아울렀다."],"ow":[[["海平面","hǎipíngmiàn","해수면"],["马尔代夫","Mǎ'ěrdàifū","몰디브"],["海拔","hǎibá","해발"]],[["河西走廊","Héxī Zǒuláng","허시 회랑"],["敦煌","Dūnhuáng","둔황"],["丝绸之路","Sīchóu zhī Lù","실크로드"],["繁盛","fánshèng","번성하다"]],[["藻类","zǎolèi","조류"],["碘","diǎn","요오드"],["甲状腺","jiǎzhuàngxiàn","갑상선"],["肿大","zhǒngdà","붓다"]],[["圆明园","Yuánmíng Yuán","원명원"],["誉为","yùwéi","~로 칭송되다"],["融汇","rónghuì","융합하다"],["园林","yuánlín","정원"]]]},{"o":["能否在日常生活中自觉养成节约用水的习惯，是缓解城市水资源紧张的有效途径。","《天工开物》是明代宋应星所著的科技著作，被国外学者称为“中国十七世纪的工艺百科全书”。","蝙蝠能够发出超声波，并依靠回声来判断前方障碍物的位置和距离。","利用大型三维打印设备，工人可以将特制的混凝土逐层堆叠，在几天内“打印”出一栋小型房屋。"],"a":0,"type":"양면–한면","why":"앞은 “能否”(할지 말지 두 면)인데 뒤의 “有效途径”는 한 면만 말해서 맞지 않는다.","fix":"在日常生活中自觉养成节约用水的习惯，是缓解城市水资源紧张的有效途径。","words":[["天工开物","Tiāngōng Kāiwù","천공개물"],["宋应星","Sòng Yìngxīng","송응성"],["百科全书","bǎikē quánshū","백과사전"],["蝙蝠","biānfú","박쥐"],["超声波","chāoshēngbō","초음파"],["堆叠","duīdié","겹겹이 쌓다"]],"tr":["일상에서 스스로 물을 아끼는 습관을 들이는 것은 도시의 물 부족을 덜 수 있는 효과적인 방법이다.","『천공개물』은 명나라 송응성이 지은 과학 기술서로, 외국 학자들에게서 '중국 17세기의 공예 백과사전'이라 불렸다.","박쥐는 초음파를 내보내고 되돌아오는 소리로 앞에 있는 장애물의 위치와 거리를 판단한다.","대형 3D 프린터를 이용하면 작업자들이 특수 콘크리트를 한 층씩 쌓아 올려 며칠 만에 작은 집 한 채를 '프린트'할 수 있다."],"ow":[[["自觉","zìjué","자발적으로"],["缓解","huǎnjiě","완화하다"],["途径","tújìng","방법, 경로"]],[["天工开物","Tiāngōng Kāiwù","천공개물"],["宋应星","Sòng Yìngxīng","송응성"],["工艺","gōngyì","공예"],["百科全书","bǎikē quánshū","백과사전"]],[["蝙蝠","biānfú","박쥐"],["超声波","chāoshēngbō","초음파"],["障碍物","zhàng'àiwù","장애물"]],[["三维","sānwéi","3차원"],["混凝土","hùnníngtǔ","콘크리트"],["逐层","zhúcéng","한 층씩"],["堆叠","duīdié","겹겹이 쌓다"]]]},{"o":["南极洲绝大部分地区常年被冰雪覆盖，冰盖的平均厚度超过两千米。","海上桥梁的钢构件长期受到盐雾侵蚀，因此必须涂刷多层防腐涂料并定期检测维护。","企业是否切实履行节能减排的社会责任，是推动经济绿色转型的重要保障。","心理学家发现，人在疲劳时更容易作出冲动的决定，这种现象被称为“决策疲劳”。"],"a":2,"type":"양면–한면","why":"앞은 “是否”(하는지 안 하는지 두 면)인데 뒤의 “重要保障”는 한 면만 말해서 맞지 않는다.","fix":"企业切实履行节能减排的社会责任，是推动经济绿色转型的重要保障。","words":[["南极洲","Nánjízhōu","남극 대륙"],["冰盖","bīnggài","빙상"],["履行","lǚxíng","이행하다"],["节能减排","jiénéng jiǎnpái","에너지 절약과 배출 감축"],["盐雾","yánwù","염무(소금기 안개)"],["侵蚀","qīnshí","침식, 부식"],["涂料","túliào","도료"]],"tr":["남극 대륙은 대부분 일 년 내내 눈과 얼음에 덮여 있고, 빙상의 평균 두께는 2,000미터가 넘는다.","바다 위 다리의 강철 부재는 오랫동안 소금기 안개에 부식되므로, 여러 겹의 방청 도료를 칠하고 정기적으로 점검·관리해야 한다.","기업이 에너지 절약과 배출 감축이라는 사회적 책임을 착실히 이행하는 것은 경제의 녹색 전환을 이끄는 중요한 보장이다.","심리학자들은 사람이 지쳤을 때 충동적인 결정을 내리기 쉽다는 것을 발견했고, 이를 '결정 피로'라고 부른다."],"ow":[[["南极洲","Nánjízhōu","남극 대륙"],["常年","chángnián","일 년 내내"],["冰盖","bīnggài","빙상"]],[["构件","gòujiàn","부재"],["盐雾","yánwù","염무(소금기 안개)"],["侵蚀","qīnshí","부식시키다"],["防腐","fángfǔ","부식 방지"],["涂料","túliào","도료"]],[["切实","qièshí","착실하게"],["履行","lǚxíng","이행하다"],["节能减排","jiénéng jiǎnpái","에너지 절약과 배출 감축"],["转型","zhuǎnxíng","전환"]],[["疲劳","píláo","피로"],["冲动","chōngdòng","충동적인"],["决策","juécè","결정"]]]},{"o":["黄河因含沙量巨大而呈现浑黄的颜色，下游河段因泥沙淤积形成了举世闻名的“地上河”。","傣族的泼水节是傣历新年，人们互相泼水，以表达驱邪除灾、祈求吉祥的美好愿望。","海獭有时会把石块放在腹部，用来砸开贝壳，是少数会使用工具的哺乳动物之一。","这次环保展览以图文结合的形式，向观众普及了垃圾分类的具体方法、废旧电池的潜在危害以及回收再利用的精美工艺品。"],"a":3,"type":"목적어 일부 호응","why":"“普及”는 방법·위험 같은 지식과는 어울리지만 마지막 목적어 “工艺品”과는 어울리지 않는다.","fix":"这次环保展览以图文结合的形式，向观众普及了垃圾分类的具体方法和废旧电池的潜在危害，并展出了回收再利用的精美工艺品。","words":[["含沙量","hánshāliàng","함사량(물속 모래 양)"],["淤积","yūjī","퇴적되다"],["傣族","Dǎizú","다이족"],["泼水节","Pōshuǐ Jié","물 뿌리기 축제"],["驱邪","qūxié","액운을 쫓다"],["海獭","hǎitǎ","해달"],["哺乳动物","bǔrǔ dòngwù","포유동물"],["普及","pǔjí","보급하다, 널리 알리다"]],"tr":["황허강은 모래가 아주 많이 섞여 누런 빛을 띠며, 하류에는 진흙과 모래가 쌓여 세상에 널리 알려진 '천정천'이 생겼다.","다이족의 물 뿌리기 축제는 다이력 새해로, 사람들은 서로 물을 뿌리며 액운을 쫓고 복을 비는 소망을 나타낸다.","해달은 가끔 배 위에 돌을 올려놓고 조개를 깨 먹는데, 도구를 쓸 줄 아는 몇 안 되는 포유동물 가운데 하나이다.","이번 환경 전시회는 그림과 글을 곁들여 관람객에게 쓰레기 분리 방법, 폐건전지의 잠재적 위험, 그리고 재활용으로 만든 정교한 공예품을 알렸다."],"ow":[[["含沙量","hánshāliàng","함사량"],["浑黄","húnhuáng","흐리고 누렇다"],["淤积","yūjī","퇴적되다"],["举世闻名","jǔ shì wén míng","세상에 널리 알려지다"]],[["傣族","Dǎizú","다이족"],["泼水节","Pōshuǐ Jié","물 뿌리기 축제"],["驱邪","qūxié","액운을 쫓다"],["祈求","qíqiú","빌다"],["吉祥","jíxiáng","길하다"]],[["海獭","hǎitǎ","해달"],["腹部","fùbù","배"],["贝壳","bèiké","조개껍데기"],["哺乳动物","bǔrǔ dòngwù","포유동물"]],[["普及","pǔjí","널리 알리다"],["潜在","qiánzài","잠재적인"],["危害","wēihài","위해"],["工艺品","gōngyìpǐn","공예품"]]]}],[{"o":["每年冬季，成千上万只白天鹅从西伯利亚飞抵山东荣成的天鹅湖越冬。","汉代张骞两次出使西域，打通了中原与西域各国之间的交通要道。","在林业专家的指导下，村民们把村子周围的荒山全部几乎种上了耐旱的沙棘和柠条。","人在阅读纸质书时，对内容的理解和记忆往往比在电子屏幕上阅读时更为深刻。"],"a":2,"type":"부사 위치","why":"“全部几乎”는 순서가 틀렸다. “几乎”가 “全部” 앞에 와야 한다.","fix":"在林业专家的指导下，村民们把村子周围的荒山几乎全部种上了耐旱的沙棘和柠条。","words":[["白天鹅","báitiān'é","큰고니"],["西伯利亚","Xībólìyà","시베리아"],["荣成","Róngchéng","룽청"],["越冬","yuèdōng","월동하다"],["张骞","Zhāng Qiān","장건"],["西域","Xīyù","서역"],["沙棘","shājí","산자나무"],["柠条","níngtiáo","카라가나(사막 관목)"]],"tr":["해마다 겨울이면 수많은 큰고니가 시베리아에서 산둥 룽청의 고니호로 날아와 겨울을 난다.","한나라 장건은 두 번 서역에 사신으로 가서 중원과 서역 여러 나라를 잇는 교통로를 열었다.","임업 전문가의 지도 아래 마을 사람들은 마을 둘레의 민둥산 거의 전부에 가뭄에 강한 산자나무와 카라가나를 심었다.","사람은 종이책을 읽을 때, 전자 화면으로 읽을 때보다 내용을 더 깊이 이해하고 오래 기억하는 경향이 있다."],"ow":[[["成千上万","chéng qiān shàng wàn","수천수만"],["白天鹅","báitiān'é","큰고니"],["西伯利亚","Xībólìyà","시베리아"],["荣成","Róngchéng","룽청"],["越冬","yuèdōng","겨울을 나다"]],[["张骞","Zhāng Qiān","장건"],["出使","chūshǐ","사신으로 가다"],["西域","Xīyù","서역"],["要道","yàodào","요로"]],[["荒山","huāngshān","민둥산"],["耐旱","nàihàn","가뭄에 강하다"],["沙棘","shājí","산자나무"],["柠条","níngtiáo","카라가나"]],[["纸质","zhǐzhì","종이로 된"],["屏幕","píngmù","화면"],["深刻","shēnkè","깊다"]]]},{"o":["研究人员发现，水葫芦在这片水域中没有几乎任何天敌，因而得以迅速蔓延，堵塞河道。","晋商在明清两代称雄商界五百余年，其创立的票号被视为近代银行的雏形。","风筝起源于春秋战国时期，最初主要用于军事侦察和传递信息。","长期处于噪声环境中，人不仅听力会受损，还可能出现烦躁、失眠等症状。"],"a":0,"type":"부정사 위치","why":"“没有几乎”는 순서가 틀렸다. “几乎”가 부정어 “没有” 앞에 와야 한다.","fix":"研究人员发现，水葫芦在这片水域中几乎没有任何天敌，因而得以迅速蔓延，堵塞河道。","words":[["水葫芦","shuǐhúlu","부레옥잠"],["蔓延","mànyán","만연하다, 퍼지다"],["堵塞","dǔsè","막다"],["晋商","Jìnshāng","산시 상인"],["票号","piàohào","표호(옛 환전·송금 기관)"],["雏形","chúxíng","원형, 초기 형태"],["侦察","zhēnchá","정찰하다"],["烦躁","fánzào","초조하다"]],"tr":["연구진은 부레옥잠이 이 수역에 천적이 거의 없어서 빠르게 퍼져 물길을 막는다는 것을 발견했다.","산시 상인은 명·청 두 왕조에 걸쳐 500여 년 동안 상계를 주름잡았고, 그들이 세운 표호는 근대 은행의 원형으로 여겨진다.","연은 춘추 전국 시대에 처음 생겼으며, 처음에는 주로 군사 정찰과 소식 전달에 쓰였다.","오랫동안 소음 속에 있으면 청력이 손상될 뿐 아니라 짜증·불면 같은 증상이 나타날 수도 있다."],"ow":[[["水葫芦","shuǐhúlu","부레옥잠"],["水域","shuǐyù","수역"],["天敌","tiāndí","천적"],["蔓延","mànyán","퍼지다"],["堵塞","dǔsè","막다"]],[["晋商","Jìnshāng","산시 상인"],["称雄","chēngxióng","패권을 쥐다"],["票号","piàohào","표호(옛 송금 기관)"],["雏形","chúxíng","원형"]],[["风筝","fēngzheng","연"],["起源","qǐyuán","기원하다"],["侦察","zhēnchá","정찰하다"]],[["噪声","zàoshēng","소음"],["受损","shòusǔn","손상되다"],["烦躁","fánzào","초조하다"],["症状","zhèngzhuàng","증상"]]]},{"o":["鄱阳湖是我国最大的淡水湖，其水位随季节涨落，素有“洪水一片，枯水一线”之说。","特长公路隧道内汽车尾气不易散出，因此常需在山体中开凿竖井，以加强隧道内的通风。","光合作用不仅为植物自身提供了养分，也为地球上的绝大多数生物提供了氧气。","面对日益严峻的电子垃圾问题，我们把废旧手机和电池应该交给专门的回收机构处理。"],"a":3,"type":"능원동사 위치","why":"능원동사 “应该”는 “把” 구 앞에 와야 한다.","fix":"面对日益严峻的电子垃圾问题，我们应该把废旧手机和电池交给专门的回收机构处理。","words":[["鄱阳湖","Póyáng Hú","포양호"],["涨落","zhǎngluò","(물이) 불었다 줄었다 하다"],["光合作用","guānghé zuòyòng","광합성"],["严峻","yánjùn","심각하다"],["竖井","shùjǐng","수직갱"],["尾气","wěiqì","배기가스"]],"tr":["포양호는 중국에서 가장 큰 민물 호수로, 물높이가 계절 따라 오르내려 '큰물 때는 한 바다, 마른 때는 한 줄기'라는 말이 있다.","아주 긴 도로 터널은 자동차 배기가스가 잘 빠지지 않아, 산속에 수직갱을 뚫어 터널 안 환기를 강화해야 하는 경우가 많다.","광합성은 식물 자신에게 양분을 줄 뿐 아니라 지구 위 대부분의 생물에게 산소를 공급한다.","갈수록 심각해지는 전자 쓰레기 문제 앞에서, 우리는 낡은 휴대폰과 건전지를 전문 회수 기관에 맡겨 처리해야 한다."],"ow":[[["鄱阳湖","Póyáng Hú","포양호"],["水位","shuǐwèi","수위"],["涨落","zhǎngluò","불었다 줄었다 하다"],["枯水","kūshuǐ","갈수"]],[["尾气","wěiqì","배기가스"],["开凿","kāizáo","뚫다"],["竖井","shùjǐng","수직갱"],["通风","tōngfēng","환기"]],[["光合作用","guānghé zuòyòng","광합성"],["养分","yǎngfèn","양분"],["氧气","yǎngqì","산소"]],[["日益","rìyì","날로"],["严峻","yánjùn","심각하다"],["回收","huíshōu","회수하다"],["机构","jīgòu","기관"]]]},{"o":["古代工匠在建造应县木塔时没有使用一根铁钉，全靠斗拱和榫卯结构相互咬合。","这位老护林员在大兴安岭坚守了四十年，林区里每一条山沟、每一片林子对他都了如指掌。","古代奥林匹克运动会起源于古希腊，每四年举行一次，赛会期间各方须遵守“神圣休战”的约定。","维生素D可以通过晒太阳在人体内自然合成，有助于促进钙的吸收。"],"a":1,"type":"개사구 위치","why":"잘 아는 사람은 산림 감시원이므로 “他对……了如指掌”이어야 한다. “对他”의 위치 때문에 주어와 대상이 뒤바뀌었다.","fix":"这位老护林员在大兴安岭坚守了四十年，他对林区里的每一条山沟、每一片林子都了如指掌。","words":[["应县木塔","Yìngxiàn Mùtǎ","잉현 목탑"],["斗拱","dǒugǒng","두공(공포)"],["榫卯","sǔnmǎo","장부 이음"],["大兴安岭","Dà Xīng'ān Lǐng","다싱안링"],["护林员","hùlínyuán","산림 감시원"],["了如指掌","liǎo rú zhǐ zhǎng","손바닥 보듯 훤하다"],["休战","xiūzhàn","휴전"]],"tr":["옛 장인들은 잉현 목탑을 지을 때 쇠못을 하나도 쓰지 않고, 오로지 두공과 장부 이음이 서로 맞물리는 힘에 기댔다.","이 노련한 산림 감시원은 다싱안링에서 40년을 지켜 왔기에, 숲속의 골짜기 하나, 숲 한 자락까지 손바닥 보듯 훤히 안다.","고대 올림픽은 고대 그리스에서 시작되어 4년마다 열렸고, 대회 기간에는 모두가 '신성한 휴전' 약속을 지켜야 했다.","비타민 D는 햇볕을 쬐면 몸속에서 저절로 합성되며, 칼슘 흡수를 돕는다."],"ow":[[["工匠","gōngjiàng","장인"],["应县木塔","Yìngxiàn Mùtǎ","잉현 목탑"],["斗拱","dǒugǒng","두공"],["榫卯","sǔnmǎo","장부 이음"],["咬合","yǎohé","맞물리다"]],[["护林员","hùlínyuán","산림 감시원"],["大兴安岭","Dà Xīng'ān Lǐng","다싱안링"],["坚守","jiānshǒu","굳게 지키다"],["了如指掌","liǎo rú zhǐ zhǎng","손바닥 보듯 훤하다"]],[["奥林匹克","Àolínpǐkè","올림픽"],["起源","qǐyuán","기원하다"],["休战","xiūzhàn","휴전"]],[["维生素","wéishēngsù","비타민"],["合成","héchéng","합성하다"],["钙","gài","칼슘"]]]},{"o":["柬埔寨的吴哥窟是世界上规模最大的庙宇建筑群，其精美的浮雕令人叹服。","古语说“橘生淮南则为橘，生于淮北则为枳”，这句话说明了环境对事物发展的影响。","这种能将农作物秸秆转化为生物燃料的新技术，对不少能源企业产生了浓厚的兴趣。","海啸通常由海底地震引发，在深海中传播速度极快，接近海岸时浪高可达数十米。"],"a":2,"type":"개사구 위치","why":"흥미를 갖는 것은 기업이므로 “不少能源企业对这种新技术产生了兴趣”여야 한다. “对” 구의 위치가 틀려 주어와 대상이 뒤바뀌었다.","fix":"不少能源企业对这种能将农作物秸秆转化为生物燃料的新技术产生了浓厚的兴趣。","words":[["吴哥窟","Wúgē Kū","앙코르와트"],["浮雕","fúdiāo","부조"],["叹服","tànfú","탄복하다"],["橘","jú","귤"],["枳","zhǐ","탱자"],["秸秆","jiēgǎn","농작물 줄기"],["生物燃料","shēngwù ránliào","바이오 연료"],["海啸","hǎixiào","쓰나미"]],"tr":["캄보디아의 앙코르와트는 세계에서 가장 큰 사원 건축군으로, 정교한 부조가 감탄을 자아낸다.","'귤이 회수 남쪽에서 나면 귤이 되고 회수 북쪽에서 나면 탱자가 된다'는 옛말은 환경이 사물의 발전에 미치는 영향을 보여 준다.","농작물 줄기를 바이오 연료로 바꿀 수 있는 이 신기술에 많은 에너지 기업이 큰 관심을 보였다.","쓰나미는 보통 해저 지진으로 일어나며, 깊은 바다에서는 아주 빠르게 퍼지고 해안에 다가오면 파도 높이가 수십 미터에 이를 수 있다."],"ow":[[["柬埔寨","Jiǎnpǔzhài","캄보디아"],["吴哥窟","Wúgē Kū","앙코르와트"],["庙宇","miàoyǔ","사원"],["浮雕","fúdiāo","부조"],["叹服","tànfú","탄복하다"]],[["橘","jú","귤"],["淮南","Huáinán","회수 남쪽"],["枳","zhǐ","탱자"]],[["农作物","nóngzuòwù","농작물"],["秸秆","jiēgǎn","농작물 줄기"],["生物燃料","shēngwù ránliào","바이오 연료"],["浓厚","nónghòu","짙다"]],[["海啸","hǎixiào","쓰나미"],["引发","yǐnfā","일으키다"],["传播","chuánbō","전파되다"]]]},{"o":["二十四节气是古人根据太阳在黄道上的位置划分的，是古代劳动人民智慧的结晶。","大气中的甲烷虽然含量远低于二氧化碳，但其温室效应却要强得多。","在埋深较大的硬岩隧道中施工时，岩体中积聚的能量可能突然释放，引发危险的岩爆。","这座小镇的街头摆放着许多用回收塑料瓶制作的造型别致的我国青年设计师的作品。"],"a":3,"type":"관형어 순서","why":"소유를 나타내는 “我国青年设计师”가 맨 앞에 와야 하는데 맨 뒤에 놓여 관형어 순서가 틀렸다.","fix":"这座小镇的街头摆放着许多我国青年设计师用回收塑料瓶制作的、造型别致的作品。","words":[["节气","jiéqì","절기"],["黄道","huángdào","황도"],["结晶","jiéjīng","결정체, 성과"],["甲烷","jiǎwán","메탄"],["别致","biézhì","독특하다"],["积聚","jījù","쌓이다"],["岩爆","yánbào","암반 파열(록버스트)"]],"tr":["24절기는 옛사람들이 황도 위 태양의 위치에 따라 나눈 것으로, 옛 노동하는 사람들의 지혜가 모인 결정체이다.","대기 중 메탄은 이산화탄소보다 양이 훨씬 적지만, 온실 효과는 훨씬 더 강하다.","깊이 묻힌 단단한 암반 터널을 팔 때, 암반 속에 쌓인 에너지가 갑자기 풀려나 위험한 암반 파열이 일어날 수 있다.","이 작은 마을 거리에는 중국 청년 디자이너들이 재활용 페트병으로 만든, 모양이 독특한 작품이 많이 놓여 있다."],"ow":[[["节气","jiéqì","절기"],["黄道","huángdào","황도"],["划分","huàfēn","나누다"],["结晶","jiéjīng","결정체"]],[["甲烷","jiǎwán","메탄"],["二氧化碳","èryǎnghuàtàn","이산화탄소"],["温室效应","wēnshì xiàoyìng","온실 효과"]],[["埋深","máishēn","매설 깊이"],["岩体","yántǐ","암반"],["积聚","jījù","쌓이다"],["岩爆","yánbào","암반 파열(록버스트)"]],[["摆放","bǎifàng","진열하다"],["回收","huíshōu","회수하다"],["造型","zàoxíng","모양"],["别致","biézhì","독특하다"]]]},{"o":["村口那条小河上横跨着有六百多年历史的古老的一座石拱桥，至今仍可供行人往来。","宋代理学家朱熹提出“格物致知”，主张通过探究事物的原理来获得知识。","隧道衬砌背后若长期积水，渗漏的地下水会逐渐腐蚀结构，因此防排水设计至关重要。","体育锻炼能促进大脑分泌内啡肽，从而在一定程度上缓解焦虑和抑郁情绪。"],"a":0,"type":"관형어 순서","why":"수량사 “一座”는 묘사하는 관형어 “有六百多年历史的”“古老的”보다 앞에 와야 한다.","fix":"村口那条小河上横跨着一座有六百多年历史的古老石拱桥，至今仍可供行人往来。","words":[["横跨","héngkuà","가로질러 걸쳐 있다"],["石拱桥","shígǒngqiáo","돌 아치교"],["朱熹","Zhū Xī","주희"],["格物致知","gé wù zhì zhī","격물치지"],["内啡肽","nèifēitài","엔도르핀"],["衬砌","chènqì","(터널) 라이닝"],["渗漏","shènlòu","새다"]],"tr":["마을 어귀 시냇물 위에는 600여 년 된 오래된 돌 아치교 하나가 걸쳐 있는데, 지금도 사람들이 건너다닌다.","송나라 성리학자 주희는 '격물치지'를 내세워, 사물의 이치를 깊이 따져 봄으로써 지식을 얻어야 한다고 주장했다.","터널 라이닝 뒤에 물이 오래 고이면 새어 든 지하수가 구조물을 서서히 부식시키므로, 방수·배수 설계가 매우 중요하다.","운동은 뇌가 엔도르핀을 분비하도록 도와, 불안과 우울한 감정을 어느 정도 덜어 준다."],"ow":[[["横跨","héngkuà","가로질러 걸쳐 있다"],["石拱桥","shígǒngqiáo","돌 아치교"],["行人","xíngrén","행인"]],[["理学家","lǐxuéjiā","성리학자"],["朱熹","Zhū Xī","주희"],["格物致知","gé wù zhì zhī","격물치지"],["探究","tànjiū","탐구하다"]],[["衬砌","chènqì","(터널) 라이닝"],["渗漏","shènlòu","새다"],["腐蚀","fǔshí","부식시키다"],["至关重要","zhì guān zhòngyào","매우 중요하다"]],[["分泌","fēnmì","분비하다"],["内啡肽","nèifēitài","엔도르핀"],["焦虑","jiāolǜ","불안"],["抑郁","yìyù","우울하다"]]]},{"o":["柴达木盆地矿产资源极为丰富，蕴藏着大量的盐、石油和天然气，有“聚宝盆”的美称。","志愿者们在海滩上清理出了一批被潮水冲上岸的塑料白色泡沫和破碎的渔网。","古琴是中国最古老的弹拨乐器之一，历代文人将“琴棋书画”中的琴列为修身养性之首。","我国古代将一年分为春、夏、秋、冬四季，又将每季分为孟、仲、季三个月。"],"a":1,"type":"관형어 순서","why":"재료를 나타내는 “塑料”는 중심어 바로 앞에 와야 하므로 색깔 “白色” 뒤에 놓아야 한다.","fix":"志愿者们在海滩上清理出了一批被潮水冲上岸的白色塑料泡沫和破碎的渔网。","words":[["柴达木","Cháidámù","차이다무(분지)"],["盆地","péndì","분지"],["蕴藏","yùncáng","매장되어 있다"],["潮水","cháoshuǐ","조수"],["泡沫","pàomò","스티로폼, 거품"],["古琴","gǔqín","고금(현악기)"],["弹拨","tánbō","(현을) 튕기다"],["修身养性","xiū shēn yǎng xìng","몸과 마음을 닦다"]],"tr":["차이다무 분지는 광물 자원이 매우 풍부해 소금·석유·천연가스가 많이 묻혀 있어 '보물 단지'라는 별명이 있다.","자원봉사자들은 해변에서 파도에 밀려 올라온 흰 스티로폼과 부서진 그물을 한가득 치웠다.","고금은 중국에서 가장 오래된 현악기 가운데 하나로, 역대 문인들은 '금기서화' 가운데 금을 몸과 마음을 닦는 첫째로 꼽았다.","중국 고대에는 한 해를 봄·여름·가을·겨울 네 계절로 나누고, 계절마다 다시 맹·중·계 석 달로 나누었다."],"ow":[[["柴达木","Cháidámù","차이다무"],["盆地","péndì","분지"],["矿产","kuàngchǎn","광물 자원"],["蕴藏","yùncáng","매장되어 있다"],["聚宝盆","jùbǎopén","보물 단지"]],[["志愿者","zhìyuànzhě","자원봉사자"],["潮水","cháoshuǐ","조수"],["泡沫","pàomò","스티로폼"],["渔网","yúwǎng","그물"]],[["古琴","gǔqín","고금"],["弹拨","tánbō","(현을) 튕기다"],["琴棋书画","qín qí shū huà","금기서화"],["修身养性","xiū shēn yǎng xìng","몸과 마음을 닦다"]],[["孟","mèng","맹(계절의 첫 달)"],["仲","zhòng","중(계절의 둘째 달)"]]]},{"o":["草原鼠害的泛滥与天敌数量的减少密切相关，因此保护鹰、狐狸等天敌十分重要。","大桥在特定风速下可能发生涡激振动，加装导流板等措施能有效抑制桥面的异常摆动。","当人们感到被理解和被接纳时，往往会更愿意敞开心扉，与他人坦诚交流。","科研人员先对采集到的湖水样本进行了化验分析，然后小心地将其密封保存并送往实验室。"],"a":3,"type":"사건 순서","why":"실험실로 보낸 뒤에 분석해야 하는데 “先化验分析，然后……送往实验室”로 순서가 뒤바뀌었다.","fix":"科研人员先将采集到的湖水样本小心地密封保存并送往实验室，然后对其进行了化验分析。","words":[["鼠害","shǔhài","쥐 피해"],["泛滥","fànlàn","범람하다, 들끓다"],["敞开心扉","chǎngkāi xīnfēi","마음을 열다"],["坦诚","tǎnchéng","솔직하다"],["化验","huàyàn","화학 검사하다"],["涡激振动","wōjī zhèndòng","와류 진동"],["导流板","dǎoliúbǎn","유도판"],["抑制","yìzhì","억제하다"]],"tr":["초원에 쥐 피해가 들끓는 것은 천적이 줄어든 것과 밀접한 관계가 있으므로, 매·여우 같은 천적을 보호하는 것이 매우 중요하다.","큰 다리는 특정 풍속에서 와류 진동이 생길 수 있는데, 유도판을 다는 등의 조치로 상판의 이상한 흔들림을 효과적으로 억제할 수 있다.","사람은 이해받고 받아들여진다고 느낄 때 마음을 더 열고 다른 사람과 솔직하게 이야기하려 한다.","연구진은 채취한 호수 물 시료를 먼저 화학 분석한 다음, 조심스럽게 밀봉해 실험실로 보냈다."],"ow":[[["鼠害","shǔhài","쥐 피해"],["泛滥","fànlàn","들끓다"],["天敌","tiāndí","천적"],["狐狸","húli","여우"]],[["涡激振动","wōjī zhèndòng","와류 진동"],["导流板","dǎoliúbǎn","유도판"],["抑制","yìzhì","억제하다"],["摆动","bǎidòng","흔들리다"]],[["接纳","jiēnà","받아들이다"],["敞开心扉","chǎngkāi xīnfēi","마음을 열다"],["坦诚","tǎnchéng","솔직하다"]],[["采集","cǎijí","채취하다"],["样本","yàngběn","시료"],["化验","huàyàn","화학 검사하다"],["密封","mìfēng","밀봉하다"]]]},{"o":["这项旨在保护长江江豚的方案经过反复论证，已经顺利实施并获得了有关部门的批准。","蚕丝由蚕吐丝结茧而来，我国是世界上最早养蚕缫丝的国家。","一些候鸟能够利用地球磁场辨别方向，在数千公里的迁徙中准确找到目的地。","南宋诗人陆游一生创作了近万首诗，是我国现存作品最多的古代诗人之一。"],"a":0,"type":"사건 순서","why":"승인을 받은 뒤에 시행하는 것인데 “实施并获得批准”으로 순서가 뒤바뀌었다.","fix":"这项旨在保护长江江豚的方案经过反复论证，已经获得了有关部门的批准并顺利实施。","words":[["旨在","zhǐzài","~을 목적으로 하다"],["江豚","jiāngtún","상괭이(양쯔강 돌고래)"],["论证","lùnzhèng","검토·논증하다"],["结茧","jiéjiǎn","고치를 짓다"],["缫丝","sāosī","실을 켜다"],["磁场","cíchǎng","자기장"],["迁徙","qiānxǐ","이동하다"],["陆游","Lù Yóu","육유"]],"tr":["창장 상괭이를 보호하기 위한 이 방안은 여러 차례 검토를 거쳐 이미 순조롭게 시행되었고 관련 기관의 승인도 받았다.","명주실은 누에가 실을 토해 고치를 지은 데서 나오며, 중국은 세계에서 가장 먼저 누에를 치고 실을 뽑은 나라이다.","일부 철새는 지구 자기장을 이용해 방향을 가려, 수천 킬로미터를 이동하면서도 목적지를 정확히 찾아간다.","남송 시인 육유는 평생 1만 수 가까운 시를 지었으며, 중국에서 작품이 가장 많이 남아 있는 옛 시인 가운데 하나이다."],"ow":[[["旨在","zhǐzài","~을 목적으로 하다"],["江豚","jiāngtún","상괭이"],["论证","lùnzhèng","검토·논증하다"],["实施","shíshī","시행하다"]],[["蚕丝","cánsī","명주실"],["结茧","jié jiǎn","고치를 짓다"],["缫丝","sāosī","실을 켜다"]],[["候鸟","hòuniǎo","철새"],["磁场","cíchǎng","자기장"],["辨别","biànbié","가려내다"],["迁徙","qiānxǐ","이동하다"]],[["陆游","Lù Yóu","육유"],["创作","chuàngzuò","창작하다"],["现存","xiàncún","현존하다"]]]}],[{"o":["夏季高温时，沥青路面在重载货车的反复碾压下容易产生车辙，影响行车安全。","元代黄道婆把海南黎族的纺织技术带回家乡松江，推动了当地棉纺织业的发展。","尽管人类已经能够登上月球，但对深海的了解程度却远不及对太空的了解。","只有把海洋保护区的面积扩大到一定规模，鱼类种群就能获得足够的恢复空间。"],"a":3,"type":"짝 오류","why":"“只有”는 “才”와 짝을 이룬다. “就”는 “只要”와 짝이다.","fix":"只有把海洋保护区的面积扩大到一定规模，鱼类种群才能获得足够的恢复空间。","words":[["黄道婆","Huáng Dàopó","황도파"],["黎族","Lízú","리족"],["纺织","fǎngzhī","방직"],["远不及","yuǎnbùjí","훨씬 못 미치다"],["种群","zhǒngqún","개체군"],["沥青","lìqīng","아스팔트"],["碾压","niǎnyā","짓눌러 다지다"],["车辙","chēzhé","바퀴 자국(소성 변형)"]],"tr":["여름철 고온에는 아스팔트 도로가 무거운 화물차에 거듭 눌려 바퀴 자국이 패기 쉬워, 주행 안전에 영향을 준다.","원나라 황도파는 하이난 리족의 방직 기술을 고향 쑹장으로 가져와 그곳 면방직업의 발전을 이끌었다.","인류는 이미 달에 오를 수 있게 되었지만, 깊은 바다에 대한 이해는 우주에 대한 이해에 훨씬 못 미친다.","해양 보호 구역의 면적을 일정한 규모까지 넓혀야만 물고기 개체군이 회복할 충분한 공간을 얻을 수 있다."],"ow":[[["沥青","lìqīng","아스팔트"],["重载","zhòngzài","무거운 짐을 실은"],["碾压","niǎnyā","짓눌러 다지다"],["车辙","chēzhé","바퀴 자국"]],[["黄道婆","Huáng Dàopó","황도파"],["黎族","Lízú","리족"],["纺织","fǎngzhī","방직"],["松江","Sōngjiāng","쑹장"]],[["尽管","jǐnguǎn","비록 ~하지만"],["深海","shēnhǎi","심해"],["远不及","yuǎn bù jí","훨씬 못 미치다"]],[["保护区","bǎohùqū","보호 구역"],["规模","guīmó","규모"],["种群","zhǒngqún","개체군"]]]},{"o":["不少新建体育场的屋顶采用了轻质的膜结构，既能遮风挡雨，又能让柔和的自然光透进场内。","即使储能技术在未来几年内取得重大突破，风力发电在短期内就难以完全取代火力发电。","与其被动地应对自然灾害，不如主动加强生态建设，从源头上降低灾害发生的风险。","狐狸的尾巴不仅能帮助它保持身体平衡，在寒冷的夜晚还能起到保暖的作用。"],"a":1,"type":"짝 오류","why":"“即使”는 “也”와 짝을 이룬다. “就”를 쓰면 짝이 맞지 않는다.","fix":"即使储能技术在未来几年内取得重大突破，风力发电在短期内也难以完全取代火力发电。","words":[["储能","chǔnéng","에너지 저장"],["突破","tūpò","돌파"],["火力发电","huǒlì fādiàn","화력 발전"],["与其","yǔqí","~하느니 차라리"],["膜结构","mójiégòu","막 구조"]],"tr":["새로 지은 경기장 상당수는 지붕에 가벼운 막 구조를 써서, 바람과 비를 막으면서도 부드러운 햇빛이 안으로 들어오게 한다.","설령 에너지 저장 기술이 앞으로 몇 년 안에 크게 발전하더라도, 풍력 발전이 단기간에 화력 발전을 완전히 대신하기는 어렵다.","자연재해에 수동적으로 대응하기보다는 생태 건설을 적극적으로 강화해 근본부터 재해 위험을 낮추는 편이 낫다.","여우의 꼬리는 몸의 균형을 잡는 데 도움이 될 뿐 아니라, 추운 밤에는 몸을 따뜻하게 해 준다."],"ow":[[["体育场","tǐyùchǎng","경기장"],["轻质","qīngzhì","가벼운"],["膜结构","mó jiégòu","막 구조"],["遮风挡雨","zhē fēng dǎng yǔ","바람과 비를 막다"]],[["储能","chǔnéng","에너지 저장"],["突破","tūpò","돌파"],["火力发电","huǒlì fādiàn","화력 발전"],["取代","qǔdài","대체하다"]],[["与其","yǔqí","~하느니"],["被动","bèidòng","수동적인"],["源头","yuántóu","근원"]],[["狐狸","húli","여우"],["平衡","pínghéng","균형"],["保暖","bǎonuǎn","보온하다"]]]},{"o":["无论是干旱少雨的西北内陆和湿润多雨的东南沿海，都面临着不同程度的水资源问题。","索穹顶是一种由拉索和压杆组成的新型屋盖结构，用钢量少，能够覆盖很大的空间。","宁可多花些时间反复核实数据，也不能让一个错误的结论误导公众。","长时间低头看手机会使颈椎承受过大的压力，久而久之容易引发颈椎病。"],"a":0,"type":"짝 오류","why":"“无论”은 “A还是B”처럼 선택을 나타내는 말과 짝을 이룬다. “和”를 쓰면 안 된다.","fix":"无论是干旱少雨的西北内陆还是湿润多雨的东南沿海，都面临着不同程度的水资源问题。","words":[["干旱","gānhàn","가뭄, 건조하다"],["湿润","shīrùn","습윤하다"],["核实","héshí","사실 확인하다"],["误导","wùdǎo","오도하다"],["颈椎","jǐngzhuī","경추"],["久而久之","jiǔ ér jiǔ zhī","오랜 시간이 지나면"],["索穹顶","suǒqióngdǐng","케이블 돔"],["屋盖","wūgài","지붕 구조"]],"tr":["가물고 비가 적은 서북 내륙이든 습하고 비가 많은 동남 연해든, 모두 정도는 다르지만 물 자원 문제를 겪고 있다.","케이블 돔은 케이블과 압축재로 이루어진 새로운 지붕 구조로, 강철이 적게 들면서도 아주 넓은 공간을 덮을 수 있다.","차라리 시간을 더 들여 자료를 거듭 확인할지언정, 잘못된 결론이 대중을 오도하게 해서는 안 된다.","오랫동안 고개를 숙이고 휴대폰을 보면 목뼈에 지나친 압력이 가해져, 시간이 지나면 목 디스크 같은 경추 질환이 생기기 쉽다."],"ow":[[["干旱","gānhàn","건조하다"],["湿润","shīrùn","습윤하다"],["沿海","yánhǎi","연해"]],[["索穹顶","suǒ qióngdǐng","케이블 돔"],["拉索","lāsuǒ","케이블"],["压杆","yāgǎn","압축재"],["屋盖","wūgài","지붕 구조"]],[["宁可","nìngkě","차라리"],["核实","héshí","사실 확인하다"],["误导","wùdǎo","오도하다"]],[["颈椎","jǐngzhuī","경추"],["承受","chéngshòu","견디다, 받다"],["久而久之","jiǔ ér jiǔ zhī","오랜 시간이 지나면"]]]},{"o":["吐鲁番盆地夏季酷热，昼夜温差大，所产的葡萄和哈密瓜格外香甜。","这家博物馆不仅收藏了大量珍贵文物，还经常举办面向青少年的公益讲座。","不但这座新型垃圾焚烧发电厂能处理全市一半以上的生活垃圾，而且还能将焚烧产生的热能转化为电能。","高层建筑在施工和使用期间都要定期进行沉降观测，一旦发现地基不均匀下沉，就须及时处理。"],"a":2,"type":"관련사 위치","why":"두 절의 주어가 같으므로 “不但”은 주어 “这座……发电厂” 뒤에 와야 한다.","fix":"这座新型垃圾焚烧发电厂不但能处理全市一半以上的生活垃圾，而且还能将焚烧产生的热能转化为电能。","words":[["吐鲁番","Tǔlǔfān","투루판"],["酷热","kùrè","몹시 덥다"],["昼夜温差","zhòuyè wēnchā","일교차"],["哈密瓜","hāmìguā","하미과(멜론)"],["公益","gōngyì","공익"],["热能","rènéng","열에너지"],["沉降","chénjiàng","침하"],["地基","dìjī","지반, 기초"]],"tr":["투루판 분지는 여름이 몹시 덥고 일교차가 커서, 그곳에서 나는 포도와 하미과가 유난히 달다.","이 박물관은 귀한 문물을 많이 소장하고 있을 뿐 아니라, 청소년을 위한 공익 강좌도 자주 연다.","이 새 쓰레기 소각 발전소는 시 전체 생활 쓰레기의 절반 이상을 처리할 뿐 아니라, 소각할 때 나오는 열에너지를 전기로 바꿀 수도 있다.","고층 건물은 공사 중과 사용 중에 모두 정기적으로 침하를 관측해야 하며, 지반이 고르지 않게 가라앉는 것이 보이면 곧바로 손써야 한다."],"ow":[[["吐鲁番","Tǔlǔfān","투루판"],["酷热","kùrè","몹시 덥다"],["昼夜温差","zhòuyè wēnchā","일교차"],["哈密瓜","hāmìguā","하미과"]],[["收藏","shōucáng","소장하다"],["文物","wénwù","문물"],["公益","gōngyì","공익"]],[["焚烧","fénshāo","소각하다"],["热能","rènéng","열에너지"],["转化","zhuǎnhuà","전환하다"]],[["沉降","chénjiàng","침하"],["观测","guāncè","관측하다"],["地基","dìjī","지반, 기초"]]]},{"o":["即使遭遇连续数月的干旱，也这种耐旱植物能依靠发达的根系从深层土壤中汲取水分。","对于出现裂缝的旧桥，工程师常在梁底粘贴碳纤维布，以较低的成本恢复其承载能力。","有些人习惯把重要的事情拖到最后一刻才做，这种行为在心理学上被称为“拖延症”。","煤炭在燃烧过程中会释放二氧化硫，这是形成酸雨的主要原因之一。"],"a":0,"type":"관련사 위치","why":"두 절의 주어가 같을 때 “也”는 주어 “这种耐旱植物” 뒤에 와야 한다. 주어 앞에 놓여 위치가 틀렸다.","fix":"即使遭遇连续数月的干旱，这种耐旱植物也能依靠发达的根系从深层土壤中汲取水分。","words":[["耐旱","nàihàn","가뭄에 강하다"],["汲取","jíqǔ","빨아들이다"],["拖延症","tuōyánzhèng","미루는 버릇"],["二氧化硫","èryǎnghuàliú","이산화황"],["酸雨","suānyǔ","산성비"],["碳纤维","tànxiānwéi","탄소 섬유"],["承载","chéngzài","하중을 견디다"]],"tr":["몇 달씩 가뭄이 이어져도 이 가뭄에 강한 식물은 발달한 뿌리로 깊은 흙에서 물을 빨아들일 수 있다.","균열이 생긴 낡은 다리에는 기술자들이 흔히 보 아래에 탄소 섬유 천을 붙여, 적은 비용으로 하중을 견디는 능력을 되살린다.","어떤 사람은 중요한 일을 마지막 순간까지 미루는 버릇이 있는데, 심리학에서는 이를 '미루는 습관'이라 부른다.","석탄은 탈 때 이산화황을 내뿜는데, 이것이 산성비가 생기는 주된 원인 가운데 하나이다."],"ow":[[["干旱","gānhàn","가뭄"],["耐旱","nàihàn","가뭄에 강하다"],["根系","gēnxì","뿌리 체계"],["汲取","jíqǔ","빨아들이다"]],[["裂缝","lièfèng","균열"],["粘贴","zhāntiē","붙이다"],["碳纤维","tànxiānwéi","탄소 섬유"],["承载","chéngzài","하중을 견디다"]],[["拖延症","tuōyánzhèng","미루는 버릇"],["习惯","xíguàn","습관"]],[["煤炭","méitàn","석탄"],["燃烧","ránshāo","연소"],["二氧化硫","èryǎnghuàliú","이산화황"],["酸雨","suānyǔ","산성비"]]]},{"o":["北斗卫星导航系统是我国自主建设的全球卫星导航系统，已广泛应用于交通、渔业和救灾等领域。","杜甫的诗广泛反映了唐朝由盛转衰的社会现实，因此被后人称为“诗史”。","尽管城市的人口密度远高于农村，但城市居民的人均碳排放量却未必高于农村居民。","由于今年夏季海水温度持续偏高，这一海域的珊瑚却出现了大面积白化现象。"],"a":3,"type":"논리 관계(역접 오용)","why":"앞이 원인(“由于”)이고 뒤가 그 결과인데 역접의 “却”를 써서 논리가 맞지 않는다.","fix":"由于今年夏季海水温度持续偏高，这一海域的珊瑚出现了大面积白化现象。","words":[["北斗","Běidǒu","베이더우(위성항법)"],["导航","dǎoháng","내비게이션"],["杜甫","Dù Fǔ","두보"],["由盛转衰","yóu shèng zhuǎn shuāi","융성에서 쇠퇴로 바뀌다"],["密度","mìdù","밀도"],["未必","wèibì","꼭 ~한 것은 아니다"],["白化","báihuà","백화"]],"tr":["베이더우 위성 항법 시스템은 중국이 스스로 만든 세계 위성 항법 시스템으로, 교통·어업·재난 구조 등에 널리 쓰이고 있다.","두보의 시는 당나라가 융성에서 쇠퇴로 바뀌던 사회 현실을 폭넓게 담아, 후대에 '시로 쓴 역사'라 불렸다.","도시의 인구 밀도는 농촌보다 훨씬 높지만, 도시 주민 1인당 탄소 배출량이 농촌 주민보다 꼭 많은 것은 아니다.","올여름 바닷물 온도가 계속 높았던 탓에 이 해역의 산호에 대규모 백화 현상이 나타났다."],"ow":[[["北斗","Běidǒu","베이더우"],["导航","dǎoháng","항법"],["自主","zìzhǔ","자주적인"],["救灾","jiùzāi","재난 구조"]],[["杜甫","Dù Fǔ","두보"],["由盛转衰","yóu shèng zhuǎn shuāi","융성에서 쇠퇴로 바뀌다"],["诗史","shīshǐ","시로 쓴 역사"]],[["密度","mìdù","밀도"],["人均","rénjūn","1인당"],["未必","wèibì","꼭 ~한 것은 아니다"]],[["海域","hǎiyù","해역"],["珊瑚","shānhú","산호"],["白化","báihuà","백화"]]]},{"o":["粤剧是岭南地区的传统戏曲，用粤语演唱，在海外华人中也拥有大量观众。","这一物种目前不仅已在全世界范围内濒临灭绝，而且在我国境内的数量也急剧减少。","碳中和是指通过植树造林、节能减排等方式，抵消自身产生的二氧化碳排放量。","法国昆虫学家法布尔用了三十多年的时间观察昆虫，写成了十卷本的《昆虫记》。"],"a":1,"type":"논리 관계(점층 오용)","why":"“不仅……而且”는 작은 범위에서 큰 범위로 나아가야 하는데 “全世界”를 먼저, “我国境内”를 나중에 써서 순서가 거꾸로다.","fix":"这一物种目前不仅在我国境内的数量急剧减少，而且在全世界范围内都已濒临灭绝。","words":[["粤剧","yuèjù","월극(광둥 오페라)"],["岭南","Lǐngnán","링난(광둥 일대)"],["灭绝","mièjué","멸종하다"],["急剧","jíjù","급격하다"],["碳中和","tànzhōnghé","탄소 중립"],["抵消","dǐxiāo","상쇄하다"],["法布尔","Fǎbù'ěr","파브르"],["昆虫记","Kūnchóng Jì","곤충기"]],"tr":["월극은 링난 지역의 전통극으로 광둥어로 노래하며, 해외 화교 사이에서도 관객이 많다.","이 종은 지금 전 세계적으로 멸종 위기에 놓였을 뿐 아니라, 중국 안에서도 개체 수가 급격히 줄었다.","탄소 중립이란 나무 심기, 에너지 절약과 배출 감축 같은 방법으로 자신이 배출한 이산화탄소를 상쇄하는 것을 말한다.","프랑스 곤충학자 파브르는 30여 년 동안 곤충을 관찰해 10권짜리 『곤충기』를 썼다."],"ow":[[["粤剧","yuèjù","월극"],["岭南","Lǐngnán","링난"],["粤语","Yuèyǔ","광둥어"],["华人","huárén","화교, 중국계"]],[["物种","wùzhǒng","종"],["濒临","bīnlín","임박하다"],["灭绝","mièjué","멸종하다"],["急剧","jíjù","급격하다"]],[["碳中和","tàn zhōnghé","탄소 중립"],["植树造林","zhí shù zào lín","나무를 심어 숲을 만들다"],["抵消","dǐxiāo","상쇄하다"]],[["昆虫学家","kūnchóng xuéjiā","곤충학자"],["法布尔","Fǎbù'ěr","파브르"],["昆虫记","Kūnchóng Jì","곤충기"]]]},{"o":["十六世纪初，葡萄牙航海家麦哲伦率领的船队完成了人类历史上首次环球航行。","我国的大熊猫保护工作成效显著，其受威胁等级已由“濒危”降为“易危”。","这种新型节能灯的价格比普通白炽灯略高，而且使用寿命长达后者的十倍以上，长期来看反而更加省钱。","每年六七月间，长江中下游地区常常进入梅雨季节，空气湿度大，物品容易发霉。"],"a":2,"type":"논리 관계(역접 오용)","why":"“값이 조금 비싸다”와 “수명이 길다”는 반대 방향의 내용이므로 “而且”가 아니라 “但”으로 이어야 한다.","fix":"这种新型节能灯的价格比普通白炽灯略高，但使用寿命长达后者的十倍以上，长期来看反而更加省钱。","words":[["葡萄牙","Pútáoyá","포르투갈"],["麦哲伦","Màizhélún","마젤란"],["环球航行","huánqiú hángxíng","세계 일주 항해"],["易危","yìwēi","취약(멸종 위기 등급)"],["白炽灯","báichìdēng","백열등"],["梅雨","méiyǔ","장마"],["发霉","fāméi","곰팡이가 피다"]],"tr":["16세기 초, 포르투갈 항해가 마젤란이 이끈 선단이 인류 역사상 처음으로 세계 일주 항해를 마쳤다.","중국의 판다 보호 사업은 성과가 뚜렷해, 위협 등급이 '위기'에서 '취약'으로 낮아졌다.","이 새 절전 전등은 일반 백열등보다 값이 조금 비싸지만, 수명이 그 열 배가 넘어 길게 보면 오히려 돈이 덜 든다.","해마다 6~7월이면 창장 중하류 지역은 장마철에 접어들어, 습도가 높고 물건에 곰팡이가 피기 쉽다."],"ow":[[["葡萄牙","Pútáoyá","포르투갈"],["航海家","hánghǎijiā","항해가"],["麦哲伦","Màizhélún","마젤란"],["环球航行","huánqiú hángxíng","세계 일주 항해"]],[["成效显著","chéngxiào xiǎnzhù","성과가 뚜렷하다"],["濒危","bīnwēi","멸종 위기"],["易危","yìwēi","취약"]],[["节能灯","jiénéngdēng","절전 전등"],["白炽灯","báichìdēng","백열등"],["寿命","shòumìng","수명"]],[["梅雨","méiyǔ","장마"],["湿度","shīdù","습도"],["发霉","fāméi","곰팡이가 피다"]]]},{"o":["杭州西湖的“断桥残雪”是西湖十景之一，冬季雪后景色尤为动人。","对于如何减少快递过度包装的问题上，各方专家在研讨会上提出了不少建设性意见。","中医认为“药食同源”，许多日常食材如山药、红枣也具有一定的药用价值。","塔式起重机是高层建筑施工中不可或缺的设备，其高度可以随着楼体的升高而不断加高。"],"a":1,"type":"개사 오용","why":"“对于……”와 “在……问题上”이 뒤섞였다. “在……问题上”이나 “对于……问题” 중 하나만 써야 한다.","fix":"在如何减少快递过度包装的问题上，各方专家在研讨会上提出了不少建设性意见。","words":[["断桥残雪","Duànqiáo Cánxuě","단교잔설(시후 10경)"],["快递","kuàidì","택배"],["研讨会","yántǎohuì","세미나"],["建设性","jiànshèxìng","건설적인"],["药食同源","yào shí tóng yuán","약과 음식은 근원이 같다"],["山药","shānyao","마"],["塔式起重机","tǎshì qǐzhòngjī","타워 크레인"],["不可或缺","bù kě huò quē","없어서는 안 되다"]],"tr":["항저우 시후의 '단교잔설'은 시후 10경 가운데 하나로, 겨울 눈 온 뒤의 경치가 특히 아름답다.","택배의 과대 포장을 어떻게 줄일지에 대해 여러 전문가가 세미나에서 건설적인 의견을 많이 내놓았다.","중의학에서는 '약과 음식은 뿌리가 같다'고 보아, 마·대추 같은 일상 식재료에도 어느 정도 약효가 있다고 여긴다.","타워 크레인은 고층 건물 공사에 없어서는 안 될 장비로, 건물이 높아짐에 따라 크레인 높이도 계속 높일 수 있다."],"ow":[[["西湖","Xī Hú","시후"],["断桥残雪","Duànqiáo Cánxuě","단교잔설"]],[["快递","kuàidì","택배"],["包装","bāozhuāng","포장"],["研讨会","yántǎohuì","세미나"],["建设性","jiànshèxìng","건설적인"]],[["中医","zhōngyī","중의학"],["药食同源","yào shí tóng yuán","약과 음식은 근원이 같다"],["山药","shānyao","마"],["红枣","hóngzǎo","대추"]],[["塔式起重机","tǎshì qǐzhòngjī","타워 크레인"],["不可或缺","bù kě huò quē","없어서는 안 되다"],["设备","shèbèi","장비"]]]},{"o":["位于四川的九寨沟以翠海、叠瀑、彩林、雪峰和藏族风情闻名，被称为“童话世界”。","这种昆虫的幼虫在地下生活长达十七年，然后才钻出地面羽化为成虫。","心理学家认为，适度的自我怀疑有助于人们保持清醒，避免盲目自信。","在国际社会的共同推动，《巴黎协定》于二〇一六年正式生效，为全球应对气候变化作出了制度安排。"],"a":3,"type":"개사 오용","why":"“在……推动” 뒤에 “下”가 빠져 개사구가 완성되지 않았다.","fix":"在国际社会的共同推动下，《巴黎协定》于二〇一六年正式生效，为全球应对气候变化作出了制度安排。","words":[["九寨沟","Jiǔzhàigōu","주자이거우"],["叠瀑","diépù","계단식 폭포"],["风情","fēngqíng","풍토와 인정"],["幼虫","yòuchóng","유충"],["羽化","yǔhuà","우화(성충이 되다)"],["盲目","mángmù","맹목적인"],["巴黎协定","Bālí Xiédìng","파리 협정"],["生效","shēngxiào","발효되다"]],"tr":["쓰촨의 주자이거우는 비취빛 호수, 계단식 폭포, 단풍 숲, 설산과 티베트족 풍습으로 이름나 '동화의 세계'로 불린다.","이 곤충의 애벌레는 땅속에서 17년이나 살다가 비로소 땅 위로 나와 날개 달린 성충이 된다.","심리학자들은 적당한 자기 의심이 정신을 맑게 하고 맹목적인 자신감을 피하는 데 도움이 된다고 본다.","국제 사회가 함께 밀어붙인 끝에 『파리 협정』은 2016년 정식으로 발효되어, 세계의 기후 변화 대응에 제도적 틀을 마련했다."],"ow":[[["九寨沟","Jiǔzhàigōu","주자이거우"],["叠瀑","diépù","계단식 폭포"],["藏族","Zàngzú","티베트족"],["风情","fēngqíng","풍토와 인정"]],[["幼虫","yòuchóng","유충"],["钻出","zuānchū","뚫고 나오다"],["羽化","yǔhuà","우화하다"],["成虫","chéngchóng","성충"]],[["怀疑","huáiyí","의심"],["清醒","qīngxǐng","맑게 깨어 있다"],["盲目","mángmù","맹목적인"]],[["巴黎协定","Bālí Xiédìng","파리 협정"],["生效","shēngxiào","발효되다"],["应对","yìngduì","대응하다"],["制度","zhìdù","제도"]]]}],[{"o":["为了防止候鸟在迁徙途中不撞上高楼的玻璃幕墙，一些城市开始在建筑外墙上加装防撞贴纸。","西安碑林汇集了自汉代以来的历代碑石与墓志，被称为“石质书库”。","很多人难免会在疲惫时选择高糖食物来提神，然而这只能带来短暂的精神振奋。","地球上的淡水仅占总水量的百分之二点五左右，而其中大部分又以冰川形式存在。"],"a":0,"type":"이중 부정","why":"“防止”(막다) 뒤에 또 “不”를 써서 ‘부딪히지 않는 것을 막는다’는 반대 뜻이 되었다.","fix":"为了防止候鸟在迁徙途中撞上高楼的玻璃幕墙，一些城市开始在建筑外墙上加装防撞贴纸。","words":[["玻璃幕墙","bōli mùqiáng","유리 커튼월"],["碑林","Bēilín","비림"],["墓志","mùzhì","묘지(묘비 글)"],["难免","nánmiǎn","~하기 마련이다"],["提神","tíshén","정신을 차리게 하다"],["振奋","zhènfèn","분발하다, 활기"],["淡水","dànshuǐ","담수"]],"tr":["철새가 이동하다가 고층 건물의 유리 커튼월에 부딪히지 않도록, 일부 도시는 건물 외벽에 충돌 방지 스티커를 붙이기 시작했다.","시안 비림은 한나라 이후 역대 비석과 묘지석을 모아 두어 '돌로 된 서고'라 불린다.","많은 사람이 지칠 때 정신을 차리려고 단 음식을 고르기 마련이지만, 이는 잠깐 기운을 북돋울 뿐이다.","지구의 민물은 전체 물의 약 2.5%에 불과하고, 그 가운데 대부분은 다시 빙하 형태로 있다."],"ow":[[["候鸟","hòuniǎo","철새"],["迁徙","qiānxǐ","이동하다"],["玻璃幕墙","bōli mùqiáng","유리 커튼월"],["外墙","wàiqiáng","외벽"]],[["碑林","Bēilín","비림"],["汇集","huìjí","모으다"],["碑石","bēishí","비석"],["墓志","mùzhì","묘지(묘비 글)"]],[["难免","nánmiǎn","~하기 마련이다"],["疲惫","píbèi","지치다"],["提神","tíshén","정신을 차리게 하다"],["振奋","zhènfèn","분발하다"]],[["淡水","dànshuǐ","민물"],["冰川","bīngchuān","빙하"]]]},{"o":["海拔越高，空气越稀薄，因此初到高原的人容易出现头痛、胸闷等高原反应。","孟子提出“民为贵，社稷次之，君为轻”，体现了以民为本的政治思想。","谁也不能否认，过度开采地下水不是造成华北平原地面沉降的重要原因之一。","混凝土中的钢筋一旦锈蚀，体积就会膨胀，进而将外层混凝土胀裂，甚至使其剥落。"],"a":2,"type":"이중 부정","why":"“不能否认”(부정할 수 없다) 뒤에 또 “不是”를 써서 말하려던 뜻과 반대가 되었다.","fix":"谁也不能否认，过度开采地下水是造成华北平原地面沉降的重要原因之一。","words":[["稀薄","xībó","희박하다"],["胸闷","xiōngmèn","가슴이 답답하다"],["社稷","shèjì","사직, 국가"],["开采","kāicǎi","채굴하다"],["沉降","chénjiàng","침하"],["锈蚀","xiùshí","녹슬다"],["剥落","bōluò","벗겨져 떨어지다"]],"tr":["해발이 높을수록 공기가 희박해지므로, 고원에 처음 간 사람은 두통·가슴 답답함 같은 고산병 증상이 나타나기 쉽다.","맹자는 '백성이 가장 귀하고, 사직이 그다음이며, 임금은 가볍다'고 하여 백성을 근본으로 삼는 정치사상을 드러냈다.","누구도 부정할 수 없듯이, 지하수를 지나치게 퍼 올린 것은 화베이 평원 지반 침하의 중요한 원인 가운데 하나다.","콘크리트 속 철근이 녹슬면 부피가 커져서 바깥 콘크리트를 터뜨리고 심하면 떨어져 나가게 만든다."],"ow":[[["海拔","hǎibá","해발"],["稀薄","xībó","희박하다"],["胸闷","xiōngmèn","가슴이 답답하다"],["高原反应","gāoyuán fǎnyìng","고산병"]],[["孟子","Mèngzǐ","맹자"],["社稷","shèjì","사직, 국가"],["以民为本","yǐ mín wéi běn","백성을 근본으로 삼다"]],[["否认","fǒurèn","부정하다"],["开采","kāicǎi","퍼 올리다"],["华北平原","Huáběi Píngyuán","화베이 평원"],["沉降","chénjiàng","침하"]],[["混凝土","hùnníngtǔ","콘크리트"],["钢筋","gāngjīn","철근"],["锈蚀","xiùshí","녹슬다"],["膨胀","péngzhàng","팽창하다"],["剥落","bōluò","벗겨져 떨어지다"]]]},{"o":["澳大利亚特有的考拉几乎只以桉树叶为食，每天大部分时间都处于睡眠状态。","在野外遇到野生动物时，切忌不要大声喧哗或随意投喂食物，以免激怒动物或改变它们的天然习性。","王安石的变法虽然最终失败，但其中的许多措施对后世产生了深远影响。","我们不得不承认，人工智能在图像识别等领域的准确率已经超过了普通人。"],"a":1,"type":"이중 부정","why":"“切忌”가 이미 ‘절대 하지 말라’는 뜻이라 “不要”를 더하면 ‘하지 않는 것을 금한다’가 되어 뜻이 뒤집힌다.","fix":"在野外遇到野生动物时，切忌大声喧哗或随意投喂食物，以免激怒动物或改变它们的天然习性。","words":[["考拉","kǎolā","코알라"],["桉树","ānshù","유칼립투스"],["切忌","qièjì","절대 삼가다"],["喧哗","xuānhuá","떠들썩하다"],["投喂","tóuwèi","먹이를 주다"],["王安石","Wáng Ānshí","왕안석"],["变法","biànfǎ","변법, 제도 개혁"]],"tr":["오스트레일리아에만 사는 코알라는 거의 유칼립투스 잎만 먹고, 하루 대부분을 잠으로 보낸다.","야외에서 야생 동물을 만나면 크게 떠들거나 함부로 먹이를 주는 일을 절대 삼가야 한다. 동물을 화나게 하거나 타고난 습성을 바꿀 수 있기 때문이다.","왕안석의 변법은 결국 실패했지만, 그 가운데 많은 조치가 후대에 깊은 영향을 끼쳤다.","인공지능이 이미지 인식 같은 분야에서 보통 사람보다 정확도가 높아졌다는 것을 우리는 인정하지 않을 수 없다."],"ow":[[["澳大利亚","Àodàlìyà","오스트레일리아"],["考拉","kǎolā","코알라"],["桉树","ānshù","유칼립투스"]],[["切忌","qièjì","절대 삼가다"],["喧哗","xuānhuá","떠들썩하다"],["投喂","tóuwèi","먹이를 주다"],["以免","yǐmiǎn","~하지 않도록"],["习性","xíxìng","습성"]],[["王安石","Wáng Ānshí","왕안석"],["变法","biànfǎ","변법, 제도 개혁"],["措施","cuòshī","조치"]],[["不得不","bùdébù","~하지 않을 수 없다"],["人工智能","réngōng zhìnéng","인공지능"],["识别","shíbié","식별하다"]]]},{"o":["三星堆遗址出土的青铜大立人像连座通高二百六十多厘米，造型奇特，工艺高超。","太阳能电池的光电转换效率在过去二十年里提高了一倍多，发电成本则下降了八成以上。","汉语中的许多成语来源于历史故事，比如“卧薪尝胆”就出自春秋时期越王勾践的经历。","采用新工艺后，这家钢铁厂每吨钢的耗水量比十年前减少了两倍，水资源循环利用率接近百分之百。"],"a":3,"type":"배수 감소","why":"줄어드는 것에는 “倍”를 쓸 수 없다. “减少了两倍”가 아니라 분수나 백분율로 말해야 한다.","fix":"采用新工艺后，这家钢铁厂每吨钢的耗水量比十年前减少了三分之二，水资源循环利用率接近百分之百。","words":[["三星堆","Sānxīngduī","싼싱두이"],["通高","tōnggāo","전체 높이"],["光电转换","guāngdiàn zhuǎnhuàn","광전 변환"],["卧薪尝胆","wò xīn cháng dǎn","와신상담"],["勾践","Gōujiàn","구천"],["循环利用","xúnhuán lìyòng","재활용, 순환 이용"]],"tr":["싼싱두이 유적에서 나온 청동 대입인상은 받침까지 전체 높이가 260여 센티미터에 이르며, 모양이 독특하고 솜씨가 뛰어나다.","태양 전지의 광전 변환 효율은 지난 20년 동안 두 배 넘게 높아졌고, 발전 비용은 80% 넘게 내려갔다.","중국어의 많은 성어는 역사 이야기에서 왔는데, 예를 들어 '와신상담'은 춘추 시대 월왕 구천의 일에서 나왔다.","새 공정을 쓴 뒤로 이 제철소의 강철 1톤당 물 사용량은 10년 전보다 크게 줄었고, 물 재순환 이용률은 100%에 가까워졌다."],"ow":[[["三星堆","Sānxīngduī","싼싱두이"],["遗址","yízhǐ","유적"],["通高","tōnggāo","전체 높이"],["高超","gāochāo","뛰어나다"]],[["光电转换","guāngdiàn zhuǎnhuàn","광전 변환"],["效率","xiàolǜ","효율"],["成本","chéngběn","비용"]],[["成语","chéngyǔ","성어"],["卧薪尝胆","wò xīn cháng dǎn","와신상담"],["勾践","Gōujiàn","구천"]],[["工艺","gōngyì","공정"],["耗水量","hàoshuǐliàng","물 소비량"],["循环利用","xúnhuán lìyòng","순환 이용"]]]},{"o":["侗族大歌是一种多声部、无指挥、无伴奏的民间合唱，有“清泉般闪光的音乐”之美称。","二十世纪以来，全球海平面已累计上升了约二十厘米，且上升速度仍在加快。","人们常说“熟能生巧”，意思是做事情只要反复练习，就能掌握其中的技巧。","经过技术改造，这座火电厂的氮氧化物排放浓度降低了一倍半，已达到国家超低排放标准。"],"a":3,"type":"배수 감소","why":"줄어드는 것에는 “倍”를 쓸 수 없다. “降低了一倍半”는 틀린 표현이고 백분율로 써야 한다.","fix":"经过技术改造，这座火电厂的氮氧化物排放浓度降低了百分之六十，已达到国家超低排放标准。","words":[["侗族大歌","Dòngzú Dàgē","둥족 다성 합창"],["声部","shēngbù","성부"],["伴奏","bànzòu","반주"],["累计","lěijì","누계"],["熟能生巧","shú néng shēng qiǎo","익숙해지면 요령이 생긴다"],["氮氧化物","dànyǎnghuàwù","질소산화물"],["超低排放","chāodī páifàng","초저배출"]],"tr":["둥족 다성 합창은 여러 성부로 지휘자도 반주도 없이 부르는 민간 합창으로, '맑은 샘물처럼 반짝이는 음악'이라는 별칭이 있다.","20세기 이후 전 세계 해수면은 모두 합해 약 20센티미터 올랐고, 오르는 속도도 계속 빨라지고 있다.","흔히 '익숙해지면 요령이 생긴다'고 하는데, 일을 거듭 연습하기만 하면 그 기술을 익힐 수 있다는 뜻이다.","기술 개조를 거쳐 이 화력 발전소의 질소산화물 배출 농도는 크게 낮아져, 이미 국가 초저배출 기준에 이르렀다."],"ow":[[["侗族大歌","Dòngzú Dàgē","둥족 다성 합창"],["声部","shēngbù","성부"],["伴奏","bànzòu","반주"],["美称","měichēng","좋은 별칭"]],[["海平面","hǎipíngmiàn","해수면"],["累计","lěijì","누계"]],[["熟能生巧","shú néng shēng qiǎo","익숙해지면 요령이 생긴다"],["掌握","zhǎngwò","익히다"],["技巧","jìqiǎo","기교"]],[["改造","gǎizào","개조하다"],["火电厂","huǒdiànchǎng","화력 발전소"],["氮氧化物","dànyǎnghuàwù","질소산화물"],["超低排放","chāodī páifàng","초저배출"]]]},{"o":["这家回收站专门收购废纸、塑料瓶、易拉罐、金属和旧衣物等可回收物。","《孙子兵法》是我国现存最早的兵书，其中“知己知彼，百战不殆”的思想至今仍被广泛引用。","河豚体内含有剧毒的河豚毒素，必须经专业人员处理后才能食用。","草原上的植物根系发达，能够牢牢固定土壤，有效防止风蚀和土地退化。"],"a":0,"type":"범위·분류 오류","why":"“易拉罐”(캔)는 “金属”(금속)에 포함되는데 둘을 나란히 늘어놓아 분류가 겹친다.","fix":"这家回收站专门收购废纸、塑料瓶、易拉罐和旧衣物等可回收物。","words":[["回收站","huíshōuzhàn","재활용품 수거소"],["易拉罐","yìlāguàn","캔(따는 캔)"],["孙子兵法","Sūnzǐ Bīngfǎ","손자병법"],["知己知彼","zhī jǐ zhī bǐ","지피지기"],["百战不殆","bǎi zhàn bú dài","백 번 싸워도 위태롭지 않다"],["河豚","hétún","복어"],["根系","gēnxì","뿌리 체계"],["风蚀","fēngshí","풍식"]],"tr":["이 수거소는 폐지, 페트병, 캔, 금속, 헌 옷 같은 재활용품을 전문으로 사들인다.","『손자병법』은 중국에 남아 있는 가장 오래된 병법서이며, 그 가운데 '지피지기면 백전불태'라는 생각은 지금도 널리 인용된다.","복어 몸에는 맹독인 테트로도톡신이 있어서, 반드시 전문가가 손질한 뒤에야 먹을 수 있다.","초원 식물은 뿌리가 잘 발달해 흙을 단단히 붙잡아 주므로, 바람에 의한 침식과 땅의 황폐화를 효과적으로 막는다."],"ow":[[["回收站","huíshōuzhàn","재활용품 수거소"],["收购","shōugòu","사들이다"],["易拉罐","yìlāguàn","캔"]],[["孙子兵法","Sūnzǐ Bīngfǎ","손자병법"],["兵书","bīngshū","병법서"],["知己知彼","zhī jǐ zhī bǐ","지피지기"],["百战不殆","bǎi zhàn bú dài","백 번 싸워도 위태롭지 않다"],["引用","yǐnyòng","인용하다"]],[["河豚","hétún","복어"],["剧毒","jùdú","맹독"],["毒素","dúsù","독소"]],[["根系","gēnxì","뿌리 체계"],["风蚀","fēngshí","풍식"],["退化","tuìhuà","퇴화, 황폐화"]]]},{"o":["古人把一昼夜分为十二个时辰，每个时辰相当于现在的两个小时。","钙是构成骨骼和牙齿的主要成分，青少年时期充足的钙摄入对骨骼发育尤为重要。","这次气候变化论坛吸引了国内外两百多位专家学者和来自美国、德国的环境科学家参加。","楷书由隶书演变而来，形体方正，笔画平直，是现代通行的标准汉字字体。"],"a":2,"type":"범위·분류 오류","why":"“国内外专家学者”에 이미 미국·독일 과학자가 포함되는데 따로 또 나열해 범위가 겹친다.","fix":"这次气候变化论坛吸引了包括美国、德国环境科学家在内的国内外两百多位专家学者参加。","words":[["一昼夜","yízhòuyè","하루 밤낮"],["时辰","shíchen","시진(옛 시간 단위)"],["骨骼","gǔgé","골격"],["论坛","lùntán","포럼"],["楷书","kǎishū","해서"],["隶书","lìshū","예서"],["演变","yǎnbiàn","변천하다"]],"tr":["옛사람들은 하루 밤낮을 열두 시진으로 나누었는데, 한 시진은 지금의 두 시간에 해당한다.","칼슘은 뼈와 이를 이루는 주성분이어서, 청소년기에 칼슘을 충분히 섭취하는 것이 뼈 발달에 특히 중요하다.","이번 기후 변화 포럼에는 국내외 전문가와 학자 200여 명, 그리고 미국·독일에서 온 환경 과학자들이 참석했다.","해서는 예서에서 변해 온 것으로, 글자 모양이 반듯하고 획이 곧아 오늘날 널리 쓰이는 표준 한자 서체이다."],"ow":[[["一昼夜","yí zhòuyè","하루 밤낮"],["时辰","shíchen","시진(옛 시간 단위)"],["相当于","xiāngdāng yú","~에 해당하다"]],[["钙","gài","칼슘"],["骨骼","gǔgé","골격"],["摄入","shèrù","섭취하다"]],[["论坛","lùntán","포럼"],["专家学者","zhuānjiā xuézhě","전문가와 학자"]],[["楷书","kǎishū","해서"],["隶书","lìshū","예서"],["演变","yǎnbiàn","변천하다"],["笔画","bǐhuà","획"],["通行","tōngxíng","통용되다"]]]},{"o":["地震波分为纵波和横波，纵波传播速度较快，因此人们往往先感到上下颠簸。","专家们断定，这片湖区的蓝藻大面积暴发大概与周边农田大量使用化肥有关。","《西游记》以唐僧师徒西天取经为主线，塑造了孙悟空这一家喻户晓的艺术形象。","适当的午睡能使大脑得到休息，但午睡时间过长反而容易让人感到昏沉。"],"a":1,"type":"자기모순","why":"“断定”(확실히 단정하다)와 “大概”(아마)가 함께 쓰여 앞뒤가 모순된다.","fix":"专家们断定，这片湖区的蓝藻大面积暴发与周边农田大量使用化肥有关。","words":[["纵波","zòngbō","종파"],["横波","héngbō","횡파"],["颠簸","diānbǒ","흔들리다"],["断定","duàndìng","단정하다"],["蓝藻","lánzǎo","남조류"],["暴发","bàofā","대량 발생하다"],["家喻户晓","jiā yù hù xiǎo","모르는 사람이 없다"],["昏沉","hūnchén","정신이 몽롱하다"]],"tr":["지진파는 종파와 횡파로 나뉘는데, 종파가 더 빨리 퍼지기 때문에 사람들은 보통 위아래 흔들림을 먼저 느낀다.","전문가들은 이 호수 지역의 남조류 대량 발생이 아마도 주변 농지의 과도한 화학 비료 사용과 관련 있다고 단정했다.","『서유기』는 삼장 법사 일행이 서천으로 불경을 구하러 가는 이야기를 줄기로, 모르는 사람이 없는 손오공이라는 인물을 만들어 냈다.","알맞은 낮잠은 뇌를 쉬게 하지만, 낮잠이 너무 길면 오히려 정신이 몽롱해지기 쉽다."],"ow":[[["地震波","dìzhènbō","지진파"],["纵波","zòngbō","종파"],["横波","héngbō","횡파"],["颠簸","diānbǒ","흔들리다"]],[["断定","duàndìng","단정하다"],["蓝藻","lánzǎo","남조류"],["暴发","bàofā","대량 발생하다"],["化肥","huàféi","화학 비료"]],[["西游记","Xīyóu Jì","서유기"],["唐僧","Táng Sēng","삼장 법사"],["取经","qǔjīng","불경을 구하다"],["家喻户晓","jiā yù hù xiǎo","모르는 사람이 없다"]],[["午睡","wǔshuì","낮잠"],["昏沉","hūnchén","정신이 몽롱하다"]]]},{"o":["位于东北的扎龙湿地是世界上唯一一处丹顶鹤繁殖地之一，每年春季都吸引大批摄影爱好者前来。","宋代以前，人们大多席地而坐，桌椅等高型家具直到宋代才逐渐普及开来。","狼群内部等级分明，通常由一对头狼带领，成员之间分工协作十分默契。","心理学研究发现，人们对自己失去的东西往往比对得到的东西更加在意。"],"a":0,"type":"자기모순","why":"“唯一”(유일한)과 “之一”(여럿 중 하나)이 함께 쓰여 모순된다.","fix":"位于东北的扎龙湿地是世界上最重要的丹顶鹤繁殖地之一，每年春季都吸引大批摄影爱好者前来。","words":[["扎龙","Zhālóng","자룽(습지)"],["丹顶鹤","dāndǐnghè","두루미"],["席地而坐","xí dì ér zuò","바닥에 앉다"],["等级分明","děngjí fēnmíng","서열이 분명하다"],["头狼","tóuláng","우두머리 늑대"],["默契","mòqì","손발이 잘 맞다"]],"tr":["동북의 자룽 습지는 세계에서 유일한 두루미 번식지 가운데 하나로, 해마다 봄이면 사진 애호가들이 많이 찾아온다.","송나라 이전에는 사람들이 대개 바닥에 앉았고, 탁자와 의자 같은 높은 가구는 송나라에 와서야 차츰 널리 퍼졌다.","늑대 무리는 서열이 분명하고 보통 한 쌍의 우두머리가 이끌며, 구성원끼리 일을 나누어 협력하는 손발이 아주 잘 맞는다.","심리학 연구에 따르면 사람은 얻은 것보다 잃은 것에 더 신경을 쓰는 경향이 있다."],"ow":[[["扎龙","Zhālóng","자룽"],["湿地","shīdì","습지"],["丹顶鹤","dāndǐnghè","두루미"],["繁殖","fánzhí","번식하다"]],[["席地而坐","xí dì ér zuò","바닥에 앉다"],["家具","jiājù","가구"],["普及","pǔjí","보급되다"]],[["等级分明","děngjí fēnmíng","서열이 분명하다"],["头狼","tóuláng","우두머리 늑대"],["协作","xiézuò","협력하다"],["默契","mòqì","손발이 잘 맞다"]],[["心理学","xīnlǐxué","심리학"],["在意","zàiyì","마음에 두다"]]]},{"o":["京剧中的脸谱色彩各有寓意，红色多表示忠勇，白色多表示奸诈。","我国是世界上竹类资源最丰富的国家之一，素有“竹子王国”之称。","这片人工林的树种全部是樟子松，此外还混种了少量耐旱的落叶松和白桦。","晒伤不仅会使皮肤发红、脱皮，长期反复晒伤还会增加患皮肤癌的风险。"],"a":2,"type":"자기모순","why":"“全部是樟子松”이라고 해 놓고 다시 “此外还混种了……”라고 해서 앞뒤가 모순된다.","fix":"这片人工林的树种绝大部分是樟子松，此外还混种了少量耐旱的落叶松和白桦。","words":[["脸谱","liǎnpǔ","검보(경극 얼굴 분장)"],["寓意","yùyì","담긴 뜻"],["忠勇","zhōngyǒng","충성스럽고 용감하다"],["奸诈","jiānzhà","간사하다"],["樟子松","zhāngzǐsōng","몽골소나무"],["落叶松","luòyèsōng","잎갈나무"],["白桦","báihuà","자작나무"],["脱皮","tuōpí","껍질이 벗겨지다"]],"tr":["경극의 검보는 색깔마다 뜻이 있어서, 빨강은 대개 충성과 용기를, 하양은 대개 간사함을 나타낸다.","중국은 세계에서 대나무 자원이 가장 풍부한 나라 가운데 하나로, 예부터 '대나무 왕국'이라 불렸다.","이 인공 숲의 나무는 전부 몽골소나무이고, 그 밖에 가뭄에 강한 잎갈나무와 자작나무도 조금 섞어 심었다.","햇볕에 타면 피부가 붉어지고 벗겨질 뿐 아니라, 오랫동안 되풀이되면 피부암 위험도 커진다."],"ow":[[["脸谱","liǎnpǔ","검보(얼굴 분장)"],["寓意","yùyì","담긴 뜻"],["忠勇","zhōngyǒng","충성스럽고 용감하다"],["奸诈","jiānzhà","간사하다"]],[["竹类","zhúlèi","대나무류"],["素有","sùyǒu","예부터 지니다"]],[["樟子松","zhāngzǐsōng","몽골소나무"],["混种","hùnzhòng","섞어 심다"],["落叶松","luòyèsōng","잎갈나무"],["白桦","báihuà","자작나무"]],[["晒伤","shàishāng","햇볕 화상"],["脱皮","tuōpí","껍질이 벗겨지다"],["皮肤癌","pífū'ái","피부암"]]]}],[{"o":["新疆喀纳斯湖的湖水会随季节和天气变换颜色，当地人称之为“变色湖”。","这一地区土地沙化加剧的主要原因，是长期以来过度放牧和盲目开垦草原所造成的。","古代书院不仅是讲学授徒的场所，也承担着藏书、刻书和祭祀先贤的功能。","一项追踪研究表明，童年时期自控力较强的人，成年后的健康状况与经济状况往往更好。"],"a":1,"type":"구식 혼합","why":"“主要原因是……”와 “是……所造成的”가 뒤섞였다. 둘 중 하나만 써야 한다.","fix":"这一地区土地沙化加剧的主要原因，是长期以来过度放牧和盲目开垦草原。","words":[["喀纳斯","Kānàsī","카나스(호수)"],["放牧","fàngmù","방목하다"],["开垦","kāikěn","개간하다"],["书院","shūyuàn","서원"],["祭祀","jìsì","제사 지내다"],["先贤","xiānxián","옛 성현"],["自控力","zìkònglì","자기 통제력"]],"tr":["신장 카나스호의 물은 계절과 날씨에 따라 색이 바뀌어, 그곳 사람들은 '색이 변하는 호수'라 부른다.","이 지역 땅의 사막화가 심해진 주된 원인은 오랫동안 지나치게 방목하고 초원을 마구 개간한 것이다.","옛 서원은 강의하고 제자를 기르는 곳이었을 뿐 아니라, 책을 모으고 찍어 내며 옛 성현에게 제사 지내는 일도 맡았다.","한 추적 연구에 따르면, 어릴 때 자기 통제력이 강했던 사람은 어른이 된 뒤 건강과 경제 형편이 더 좋은 경우가 많다."],"ow":[[["喀纳斯","Kānàsī","카나스(호수)"],["变换","biànhuàn","바꾸다"]],[["沙化","shāhuà","사막화"],["放牧","fàngmù","방목하다"],["盲目","mángmù","맹목적인"],["开垦","kāikěn","개간하다"]],[["书院","shūyuàn","서원"],["授徒","shòutú","제자를 가르치다"],["祭祀","jìsì","제사 지내다"],["先贤","xiānxián","옛 성현"]],[["追踪","zhuīzōng","추적하다"],["自控力","zìkònglì","자기 통제력"],["状况","zhuàngkuàng","형편, 상황"]]]},{"o":["雅鲁藏布大峡谷是世界上最深的峡谷之一，谷内从热带到寒带的植被垂直分布十分明显。","洛阳牡丹自隋唐时期起便享有盛名，至今已有一千四百多年的栽培历史。","古人之所以重视“慎独”，是因为他们认为一个人独处时的言行最能体现其真实品格。","这项“蓝色海湾”整治行动以修复受损的近岸海域生态、恢复海岸线自然风貌为目的而实施的。"],"a":3,"type":"구식 혼합","why":"“以……为目的”와 “是……而实施的”가 뒤섞였다. 끝의 “的”와 짝이 될 “是”가 없다.","fix":"这项“蓝色海湾”整治行动是以修复受损的近岸海域生态、恢复海岸线自然风貌为目的而实施的。","words":[["雅鲁藏布","Yǎlǔ Zàngbù","얄룽창포"],["峡谷","xiágǔ","협곡"],["垂直分布","chuízhí fēnbù","수직 분포"],["牡丹","mǔdan","모란"],["栽培","zāipéi","재배하다"],["慎独","shèndú","홀로 있을 때 삼가다"],["整治","zhěngzhì","정비하다"]],"tr":["얄룽창포 대협곡은 세계에서 가장 깊은 협곡 가운데 하나로, 골짜기 안에는 열대부터 한대까지의 식생이 높이에 따라 뚜렷이 나뉘어 있다.","뤄양 모란은 수·당 시대부터 이름이 높았으며, 지금까지 1,400여 년의 재배 역사를 지니고 있다.","옛사람들이 '신독'을 중시한 것은, 혼자 있을 때의 말과 행동이 그 사람의 참된 품성을 가장 잘 드러낸다고 보았기 때문이다.","이번 '푸른 만' 정비 사업은 손상된 연안 해역의 생태를 복원하고 해안선의 자연 경관을 되살리는 것을 목적으로 시행되었다."],"ow":[[["雅鲁藏布","Yǎlǔ Zàngbù","얄룽창포"],["峡谷","xiágǔ","협곡"],["植被","zhíbèi","식생"],["垂直分布","chuízhí fēnbù","수직 분포"]],[["洛阳","Luòyáng","뤄양"],["牡丹","mǔdan","모란"],["享有盛名","xiǎngyǒu shèngmíng","명성을 누리다"],["栽培","zāipéi","재배하다"]],[["慎独","shèndú","홀로 있을 때 삼가다"],["独处","dúchǔ","혼자 지내다"],["品格","pǐngé","품성"]],[["整治","zhěngzhì","정비하다"],["修复","xiūfù","복원하다"],["海岸线","hǎi'ànxiàn","해안선"],["风貌","fēngmào","경관, 모습"]]]},{"o":["北方一些干旱地区的农业灌溉，长期以来主要靠抽取地下水为主，导致地下水位持续下降。","在古代中国，玉被视为君子美德的象征，所谓“君子比德于玉”。","科学家估计，地球上已被描述和命名的物种只占全部物种的一小部分。","唐代长安城规模宏大、布局严整，城内设有东、西两市，是当时世界上最繁华的国际大都市之一。"],"a":0,"type":"구식 혼합","why":"“靠……”와 “以……为主”가 뒤섞였다. “主要靠抽取地下水”나 “以抽取地下水为主” 중 하나만 써야 한다.","fix":"北方一些干旱地区的农业灌溉，长期以来主要靠抽取地下水，导致地下水位持续下降。","words":[["地下水位","dìxià shuǐwèi","지하수위"],["君子","jūnzǐ","군자"],["比德","bǐdé","덕을 견주다"],["命名","mìngmíng","명명하다"],["宏大","hóngdà","웅대하다"],["严整","yánzhěng","가지런하다"],["长安","Cháng'ān","장안"]],"tr":["북방 일부 건조 지역의 농업 관개는 오랫동안 주로 지하수를 퍼 올리는 데 기대어, 지하수위가 계속 내려가고 있다.","고대 중국에서 옥은 군자의 미덕을 상징했는데, 이른바 '군자는 덕을 옥에 견준다'는 말이 그것이다.","과학자들은 지구에서 이미 기술되고 이름이 붙은 생물 종이 전체 종 가운데 일부에 지나지 않는다고 추정한다.","당나라 장안성은 규모가 크고 짜임새가 반듯했으며 성안에 동시와 서시가 있어, 당시 세계에서 가장 번화한 국제 도시 가운데 하나였다."],"ow":[[["干旱","gānhàn","건조하다"],["灌溉","guàngài","관개하다"],["抽取","chōuqǔ","퍼 올리다"],["地下水位","dìxià shuǐwèi","지하수위"]],[["君子","jūnzǐ","군자"],["美德","měidé","미덕"],["象征","xiàngzhēng","상징"],["比德","bǐdé","덕을 견주다"]],[["描述","miáoshù","기술하다"],["命名","mìngmíng","명명하다"],["物种","wùzhǒng","종"]],[["长安","Cháng'ān","장안"],["宏大","hóngdà","웅대하다"],["严整","yánzhěng","가지런하다"],["繁华","fánhuá","번화하다"]]]},{"o":["被称为“地球之肺”的亚马孙雨林，近年来因非法砍伐和山火而面积锐减。","二胡是我国传统的拉弦乐器，音色柔美，善于表现委婉深沉的情感。","这座城市空气质量的明显好转，是多年来坚持调整能源结构、淘汰落后产能的结果所致。","人们越是刻意压抑某个念头，这个念头反而越容易在脑海中反复出现。"],"a":2,"type":"구식 혼합","why":"“是……的结果”와 “是……所致”가 뒤섞였다. “所致”를 빼야 한다.","fix":"这座城市空气质量的明显好转，是多年来坚持调整能源结构、淘汰落后产能的结果。","words":[["亚马孙","Yàmǎsūn","아마존"],["砍伐","kǎnfá","벌목하다"],["锐减","ruìjiǎn","급감하다"],["二胡","èrhú","얼후"],["委婉","wěiwǎn","완곡하다"],["产能","chǎnnéng","생산 능력"],["压抑","yāyì","억누르다"]],"tr":["'지구의 허파'라 불리는 아마존 우림은 최근 불법 벌목과 산불 때문에 면적이 크게 줄었다.","얼후는 중국 전통 찰현악기로 음색이 부드럽고 아름다워, 완곡하고 깊은 감정을 잘 표현한다.","이 도시의 공기가 눈에 띄게 좋아진 것은 여러 해 동안 꾸준히 에너지 구조를 바꾸고 낙후한 생산 설비를 없앤 결과다.","사람은 어떤 생각을 일부러 억누를수록 그 생각이 오히려 머릿속에 더 자주 떠오른다."],"ow":[[["亚马孙","Yàmǎsūn","아마존"],["雨林","yǔlín","우림"],["砍伐","kǎnfá","벌목하다"],["锐减","ruìjiǎn","급감하다"]],[["二胡","èrhú","얼후"],["拉弦","lāxián","활로 켜는 현"],["音色","yīnsè","음색"],["委婉","wěiwǎn","완곡하다"]],[["好转","hǎozhuǎn","호전되다"],["淘汰","táotài","도태시키다"],["产能","chǎnnéng","생산 능력"]],[["刻意","kèyì","일부러"],["压抑","yāyì","억누르다"],["念头","niàntou","생각"],["脑海","nǎohǎi","머릿속"]]]},{"o":["庐山以“雄、奇、险、秀”闻名，历代文人墨客在此留下了大量诗词和石刻。","南方春季常见的“回南天”，是暖湿气流遇到冰冷的墙面和地面后凝结成水珠而形成的。","一些研究者认为，经常接触大自然有助于缓解儿童注意力不集中等问题。","作为全球最大的可再生能源生产国，近年来新增的风电和光伏装机容量已连续多年位居世界首位。"],"a":3,"type":"주어 결여","why":"“作为……生产国”이 가리킬 주어(“我国”)가 없다. “装机容量”은 생산국이 될 수 없다.","fix":"作为全球最大的可再生能源生产国，我国新增的风电和光伏装机容量已连续多年位居世界首位。","words":[["庐山","Lú Shān","루산"],["文人墨客","wénrén mòkè","문인과 묵객"],["回南天","huínántiān","(봄철 남부의) 결로 날씨"],["凝结","níngjié","응결하다"],["可再生能源","kě zàishēng néngyuán","재생 에너지"],["装机容量","zhuāngjī róngliàng","설비 용량"],["位居","wèijū","(순위에) 자리하다"]],"tr":["루산은 '웅장하고 기이하며 험하고 수려함'으로 이름나, 역대 문인과 묵객들이 이곳에 시와 바위 글씨를 많이 남겼다.","남방의 봄에 흔한 '후이난톈'은 따뜻하고 습한 공기가 차가운 벽과 바닥에 닿아 물방울로 맺히면서 생긴다.","일부 연구자들은 자연을 자주 접하면 아이들의 주의력 결핍 같은 문제를 덜 수 있다고 본다.","세계 최대의 재생 에너지 생산국으로서, 최근 새로 늘어난 풍력·태양광 설비 용량은 여러 해 연속 세계 1위를 차지했다."],"ow":[[["庐山","Lú Shān","루산"],["文人墨客","wénrén mòkè","문인과 묵객"],["石刻","shíkè","석각"]],[["回南天","huínántiān","(봄철 남부의) 결로 날씨"],["气流","qìliú","기류"],["凝结","níngjié","응결하다"]],[["接触","jiēchù","접하다"],["缓解","huǎnjiě","완화하다"],["注意力","zhùyìlì","주의력"]],[["可再生能源","kě zàishēng néngyuán","재생 에너지"],["光伏","guāngfú","태양광"],["装机容量","zhuāngjī róngliàng","설비 용량"],["位居","wèijū","자리하다"]]]},{"o":["《论语》是记录孔子及其弟子言行的语录体著作，是儒家的经典之一。","为了避免类似的外来物种入侵事件不再发生，海关部门进一步加强了对进口苗木和花卉的检疫。","地球自转速度的微小变化会影响一天的长度，科学家为此偶尔会在协调世界时中加入“闰秒”。","北京冬奥会场馆大量采用了二氧化碳跨临界直冷制冰技术，碳排放趋近于零。"],"a":1,"type":"이중 부정","why":"“避免”(피하다) 뒤에 “不再”를 써서 ‘다시 일어나지 않는 것을 피한다’는 반대 뜻이 되었다.","fix":"为了避免类似的外来物种入侵事件再次发生，海关部门进一步加强了对进口苗木和花卉的检疫。","words":[["论语","Lúnyǔ","논어"],["语录体","yǔlùtǐ","어록체"],["儒家","Rújiā","유가"],["检疫","jiǎnyì","검역"],["苗木","miáomù","묘목"],["自转","zìzhuàn","자전"],["闰秒","rùnmiǎo","윤초"],["跨临界","kuàlínjiè","초임계를 넘나드는"]],"tr":["『논어』는 공자와 제자들의 말과 행동을 기록한 어록체 책으로, 유가의 경전 가운데 하나이다.","비슷한 외래종 침입 사건이 다시 일어나지 않도록, 세관은 수입 묘목과 꽃의 검역을 더욱 강화했다.","지구 자전 속도의 작은 변화는 하루의 길이에 영향을 주기 때문에, 과학자들은 가끔 협정 세계시에 '윤초'를 넣는다.","베이징 동계 올림픽 경기장은 이산화탄소 초임계 직접 냉각 제빙 기술을 널리 써서 탄소 배출이 거의 없었다."],"ow":[[["论语","Lúnyǔ","논어"],["语录体","yǔlùtǐ","어록체"],["儒家","Rújiā","유가"],["经典","jīngdiǎn","경전"]],[["入侵","rùqīn","침입하다"],["海关","hǎiguān","세관"],["苗木","miáomù","묘목"],["检疫","jiǎnyì","검역"]],[["自转","zìzhuàn","자전"],["协调世界时","xiétiáo shìjièshí","협정 세계시"],["闰秒","rùnmiǎo","윤초"]],[["冬奥会","Dōng'àohuì","동계 올림픽"],["跨临界","kuà línjiè","초임계를 넘나드는"],["制冰","zhìbīng","얼음을 만들다"],["趋近于","qūjìn yú","~에 가까워지다"]]]},{"o":["这次科考队在北冰洋海域采集了大量海水、海冰和浮游生物的样本，填补了我国在该领域的研究。","蒙古包便于拆装和搬迁，非常适合逐水草而居的游牧生活。","战国时期的思想家荀子认为“人之性恶”，主张通过后天的教育和礼法来改造人性。","有研究认为，与他人一起进餐时，人们往往会在不知不觉中吃得比独自进餐时更多。"],"a":0,"type":"중심어 결여","why":"“填补了……研究”는 말이 안 된다. 메운 것은 연구의 “空白”인데 그 중심어가 빠졌다.","fix":"这次科考队在北冰洋海域采集了大量海水、海冰和浮游生物的样本，填补了我国在该领域的研究空白。","words":[["北冰洋","Běibīng Yáng","북극해"],["浮游生物","fúyóu shēngwù","플랑크톤"],["填补","tiánbǔ","메우다"],["蒙古包","ménggǔbāo","게르(몽골 천막)"],["逐水草而居","zhú shuǐcǎo ér jū","물과 풀을 따라 옮겨 살다"],["游牧","yóumù","유목"],["荀子","Xúnzǐ","순자"],["礼法","lǐfǎ","예법"]],"tr":["이번에 과학 조사단은 북극해에서 바닷물·해빙·플랑크톤 시료를 많이 채취해, 이 분야에서 중국 연구의 빈자리를 메웠다.","게르는 해체하고 조립하며 옮기기가 쉬워, 물과 풀을 따라 옮겨 사는 유목 생활에 아주 알맞다.","전국 시대 사상가 순자는 '사람의 본성은 악하다'고 보고, 후천적인 교육과 예법으로 본성을 고쳐야 한다고 주장했다.","어떤 연구에 따르면, 사람들은 남과 함께 밥을 먹을 때 혼자 먹을 때보다 자신도 모르게 더 많이 먹는 경향이 있다."],"ow":[[["科考队","kēkǎoduì","과학 조사단"],["北冰洋","Běibīng Yáng","북극해"],["浮游生物","fúyóu shēngwù","플랑크톤"],["填补","tiánbǔ","메우다"]],[["蒙古包","ménggǔbāo","게르"],["拆装","chāizhuāng","해체·조립하다"],["逐水草而居","zhú shuǐcǎo ér jū","물과 풀을 따라 옮겨 살다"],["游牧","yóumù","유목"]],[["荀子","Xúnzǐ","순자"],["后天","hòutiān","후천적"],["礼法","lǐfǎ","예법"]],[["进餐","jìncān","식사하다"],["不知不觉","bù zhī bù jué","자신도 모르게"]]]},{"o":["北极地区的永久冻土一旦大面积融化，其中封存的大量温室气体就会释放到大气中。","宋代女词人李清照前期词作清丽婉约，南渡后则多抒发国破家亡的哀愁。","只要这项海水淡化技术的成本能进一步降低，才有可能在缺水的沿海城市大规模推广。","长期熬夜会扰乱人体的生物钟，进而影响内分泌和免疫功能。"],"a":2,"type":"짝 오류","why":"“只要”는 “就”와 짝이고 “才”는 “只有”와 짝이다. 짝이 맞지 않는다.","fix":"只有这项海水淡化技术的成本能进一步降低，才有可能在缺水的沿海城市大规模推广。","words":[["永久冻土","yǒngjiǔ dòngtǔ","영구 동토"],["封存","fēngcún","봉해 두다"],["李清照","Lǐ Qīngzhào","이청조"],["婉约","wǎnyuē","완곡하고 함축적이다"],["哀愁","āichóu","애수"],["生物钟","shēngwùzhōng","생체 시계"],["扰乱","rǎoluàn","어지럽히다"],["内分泌","nèifēnmì","내분비"]],"tr":["북극의 영구 동토가 넓게 녹으면, 그 속에 갇혀 있던 많은 온실가스가 대기로 풀려나게 된다.","송나라 여성 사인 이청조는 초기 작품이 맑고 완곡했으나, 남쪽으로 내려간 뒤에는 나라와 집을 잃은 슬픔을 주로 노래했다.","이 해수 담수화 기술은 비용이 더 내려가야만 물이 부족한 연안 도시에 대규모로 보급될 수 있다.","오랫동안 밤을 새우면 몸의 생체 시계가 흐트러지고, 나아가 내분비와 면역 기능에 영향을 준다."],"ow":[[["永久冻土","yǒngjiǔ dòngtǔ","영구 동토"],["融化","rónghuà","녹다"],["封存","fēngcún","봉해 두다"],["温室气体","wēnshì qìtǐ","온실가스"]],[["李清照","Lǐ Qīngzhào","이청조"],["婉约","wǎnyuē","완곡하고 함축적이다"],["抒发","shūfā","표현하다"],["哀愁","āichóu","애수"]],[["海水淡化","hǎishuǐ dànhuà","해수 담수화"],["成本","chéngběn","비용"],["推广","tuīguǎng","보급하다"]],[["熬夜","áoyè","밤을 새우다"],["扰乱","rǎoluàn","어지럽히다"],["生物钟","shēngwùzhōng","생체 시계"],["内分泌","nèifēnmì","내분비"],["免疫","miǎnyì","면역"]]]},{"o":["在高架道路穿过居民区的路段，常设置透明的声屏障，以降低交通噪声对居民的干扰。","得益于“三北”防护林等生态工程的持续建设，近年来我国北方沙尘暴的发生次数和强度都明显减弱。","苏州评弹用吴侬软语说唱，曲调优美、韵味醇厚，深受江南百姓的喜爱。","研究者认为，适当的“留白”能给人以想象空间，这一点在中国传统山水画中体现得尤为突出。"],"a":1,"type":"주어–술어","why":"“强度”는 “减弱”와 어울리지만 “次数”는 “减少”와 어울려야 한다. 주어 일부가 술어와 맞지 않는다.","fix":"得益于“三北”防护林等生态工程的持续建设，近年来我国北方沙尘暴的发生次数明显减少，强度也明显减弱。","words":[["防护林","fánghùlín","방호림"],["沙尘暴","shāchénbào","모래 폭풍"],["评弹","píngtán","평탄(쑤저우 설창 예술)"],["吴侬软语","Wú nóng ruǎn yǔ","부드러운 우(吳) 지방 말씨"],["醇厚","chúnhòu","진하고 깊다"],["留白","liúbái","여백을 남기다"],["声屏障","shēngpíngzhàng","방음벽"],["高架","gāojià","고가(도로)"]],"tr":["고가 도로가 주택가를 지나는 구간에는 흔히 투명한 방음벽을 세워, 교통 소음이 주민을 방해하는 것을 줄인다.","'삼북' 방호림 같은 생태 공사가 꾸준히 이어진 덕분에, 최근 중국 북방의 모래 폭풍은 횟수도 줄고 세기도 눈에 띄게 약해졌다.","쑤저우 평탄은 부드러운 쑤저우 말씨로 이야기하고 노래하는데, 가락이 아름답고 맛이 깊어 강남 사람들에게 큰 사랑을 받는다.","연구자들은 알맞은 '여백'이 상상할 공간을 준다고 보는데, 이 점은 중국 전통 산수화에서 특히 두드러진다."],"ow":[[["高架","gāojià","고가"],["路段","lùduàn","구간"],["声屏障","shēng píngzhàng","방음벽"],["噪声","zàoshēng","소음"],["干扰","gānrǎo","방해하다"]],[["得益于","déyì yú","~덕분이다"],["防护林","fánghùlín","방호림"],["沙尘暴","shāchénbào","모래 폭풍"],["强度","qiángdù","세기"]],[["评弹","píngtán","평탄(설창 예술)"],["吴侬软语","Wú nóng ruǎn yǔ","부드러운 우 지방 말씨"],["韵味","yùnwèi","운치"],["醇厚","chúnhòu","진하고 깊다"]],[["留白","liúbái","여백을 남기다"],["山水画","shānshuǐhuà","산수화"],["突出","tūchū","두드러지다"]]]},{"o":["长沙窑是唐代著名的民间瓷窑，率先将诗文书写在瓷器上作为装饰。","在全球变暖的背景下，青藏高原的升温速度约为全球平均水平的两倍，冰川退缩十分明显。","美学家朱光潜认为，人们只有与审美对象保持适当的“心理距离”，才能真正领略其中的美。","鉴于近年来极端暴雨事件频发，使许多城市开始重新评估地下排水系统的承载能力。"],"a":3,"type":"주어 결여","why":"“鉴于……，使……” 때문에 주어가 없다. “使”를 빼야 “许多城市”가 주어가 된다.","fix":"鉴于近年来极端暴雨事件频发，许多城市开始重新评估地下排水系统的承载能力。","words":[["长沙窑","Chángshā Yáo","창사요(당대 가마)"],["率先","shuàixiān","앞장서다"],["退缩","tuìsuō","후퇴하다, 줄어들다"],["朱光潜","Zhū Guāngqián","주광첸(미학자)"],["领略","lǐnglüè","음미하다, 깨닫다"],["鉴于","jiànyú","~을 감안하여"],["承载","chéngzài","감당하다, 수용하다"]],"tr":["창사요는 당나라의 이름난 민간 가마로, 처음으로 시구를 도자기에 써서 장식으로 삼았다.","지구 온난화 속에서 칭짱고원의 기온 상승 속도는 세계 평균의 약 두 배이며, 빙하가 줄어드는 것이 매우 뚜렷하다.","미학자 주광첸은 사람이 감상 대상과 알맞은 '심리적 거리'를 두어야만 그 아름다움을 제대로 느낄 수 있다고 보았다.","최근 극단적인 폭우가 자주 일어나는 것을 고려해, 많은 도시가 지하 배수 시스템의 수용 능력을 다시 평가하기 시작했다."],"ow":[[["长沙窑","Chángshā Yáo","창사요"],["瓷窑","cíyáo","도자기 가마"],["率先","shuàixiān","앞장서다"],["装饰","zhuāngshì","장식"]],[["全球变暖","quánqiú biànnuǎn","지구 온난화"],["青藏高原","Qīng-Zàng Gāoyuán","칭짱고원"],["冰川","bīngchuān","빙하"],["退缩","tuìsuō","줄어들다"]],[["美学家","měixuéjiā","미학자"],["朱光潜","Zhū Guāngqián","주광첸"],["审美","shěnměi","심미"],["领略","lǐnglüè","음미하다"]],[["鉴于","jiànyú","~을 감안하여"],["极端","jíduān","극단적인"],["排水","páishuǐ","배수"],["承载","chéngzài","감당하다"]]]}]];
